// Code written by Gabriel Mailhot, 10/09/2026.
// GENERATED ONCE from the doc comment sitting on each console command, then owned by hand.
//
// Gabriel, 2026-09-10: "les joueurs utilisent beaucoup les commandes consoles. Ce serait bien qu'elles
// soient bien documentees." They were not: cr.help described 70 of 259, so cr.testall itself was
// invisible, and one entry named a command renamed away months earlier.
//
// The prose started as harvest, not invention. 251 of the 259 commands already carried a good doc comment,
// usually opening with its own usage line, so those were tidied rather than rewritten and the remaining
// eight were written by hand. Shipping the compiler's XML documentation file instead was tried and
// rejected: 1.87 MB, and it would put every internal implementation note in every player's mod folder.
//
// THEN THE THIRTY-ODD A PLAYER ACTUALLY TYPES WERE REWRITTEN FOR A PLAYER. Harvested developer prose is
// accurate and aimed at the wrong reader: "dev-truth dump", "exercises the real bridge path", "the
// spike", "before the encyclopedia button is wired" mean nothing to someone trying to unstick their
// game. cr.memory, cr.reset, cr.info, cr.grudges and their neighbours now say what they do and why you
// would want them. The rest keep the developer voice, which is honest about who they are for.
//
// This file is GENERATED ONCE and OWNED BY HAND thereafter. Re-running any generator over it would throw
// those rewrites away.
//
// THE RULE THAT KEEPS THIS HONEST: cr.testall console_help_complete fails when a registered command has
// no entry here. Adding a command therefore means adding its line, and the help can no longer fall
// behind in silence, which is the only way it has ever fallen behind.

#region

using System;
using System.Collections.Generic;
using CalradiaRemembers.Logic;

#endregion

namespace CalradiaRemembers.Diagnostics
{
   /// <summary>Every cr command, described. See the file header for why this exists and what keeps it complete.</summary>
   public static class ConsoleCommandHelp
   {
      /// <summary>Command name (without the "cr." prefix) to its description. Ordinal-insensitive lookup.</summary>
      public static readonly IReadOnlyDictionary<string, ConsoleCommandDoc> All =
         new Dictionary<string, ConsoleCommandDoc>(StringComparer.OrdinalIgnoreCase) {
            ["action_bench"] = new ConsoleCommandDoc("[passes]", "Interpreter extraction bench: runs every ActionBenchCatalog case (a hand-written NPC reply paired with the action(s) it should, or must not, produce) through the configured interpreter model, scores each, and writes a per-case scoreboard to CalradiaRemembers_action_bench.log. Misses and false positives point at the tell or anti-pattern to tighten in GameActionCatalog. [passes] defaults to 1; pass a higher count (e.g. cr.action_bench 3) to run each case several times and judge it by MAJORITY, so a nondeterministic model's dice do not read as a stable failure. Real-LLM tool (spends tokens), deliberately NOT part of cr.testall, but far cheaper than it (short interpreter-only calls). Read the log to act on it. Add \"focus\" (e.g. cr.action_bench 3 focus) to run only the curated failing/flaky slice plus its canaries instead of all 220 cases: ~85% cheaper for a refinement loop. Run the full corpus (no \"focus\") once before release, since the focus slice is blind to the cases it omits."),
            ["actions_panel"] = new ConsoleCommandDoc("[on|off]", "Switches the Actions panel on or off for this session (not saved). It ships off in 2.5.22 because its layout has not been seen in game; off, the Actions tile opens the vanilla menu. Only the Classic skin draws it (cr.skin classic), so every other skin keeps the menu either way. cr.reload_ui re-reads its layout on an open chat."),
            ["add_kink"] = new ConsoleCommandDoc("<kink> [name]", "Adds a kink to the NPC's romantic profile so scene variety can be tested. Apply BEFORE opening a captive scene (cr.crc_scene re-reads the profile on open)."),
            ["ambush"] = new ConsoleCommandDoc("[name]", "Arms a town ambush (\"stance with teeth\", increment 3) against the player by the named lord (or the conversation NPC). If you are already in a town it springs at once; otherwise walk into one and it may."),
            ["ambush_audience"] = new ConsoleCommandDoc("[name]", "TEST (3.2b): open the gloating audience with the named lord (or the conversation NPC) now: the captor lord receives the captured player and savours it. Skips the convoy journey."),
            ["ambush_gate"] = new ConsoleCommandDoc("[town]", "TEST: opens the alley fight for a named town (or the first town) while the player is ON THE MAP, to see whether OpenAlleyFightMission can launch from a map context (the \"fight at the gates\" hypothesis). Stand outside a town, not inside it, and run this."),
            ["ambush_lose"] = new ConsoleCommandDoc("[name]", "Simulates LOSING a town ambush (\"stance with teeth\", increment 3.2a): the named lord's (or the conversation NPC's) cutthroats take the player prisoner and convoy them toward the lord's seat."),
            ["ambush_scene"] = new ConsoleCommandDoc("<locationId> [name]", "TEST: spring the in-town ambush forcing a specific location id as the fight scene: to hunt which one renders a coherent enclosed brawl instead of OpenAlleyFightMission's siege fallback. Stand INSIDE a town and try: tavern, house_1, house_2, port, arena, center. The paymaster is the named NPC, else any armed assassin, else any lord."),
            ["api_probe"] = new ConsoleCommandDoc("[name]", "Smoke-tests the public Extension Surface memory API: prints the API version and the loaded save's stable id, and, when a name resolves, injects a test memory via CrNpcMemory.AddMemory then reads it back via GetMemories, so a modder can confirm the read/write door works end to end."),
            ["appearance"] = new ConsoleCommandDoc("[clear | <prose...>]", "No args: shows the player's composed appearance block (derived facts + authored prose) as the NPC would read it. \"clear\": wipes the authored prose. Anything else: sets the authored prose to that text. This is the interim edit surface for the appearance pillar until the in-Encyclopedia field lands."),
            ["appreciation_backfill"] = new ConsoleCommandDoc("", "Force-reruns the one-shot migration scan regardless of the stamped version, reporting how many appreciations formed vs were skipped. Idempotent: running it again in the same session forms nothing new (the deterministic holder+source+day id dedups), which this command calls out explicitly so a second run's zero-formed result reads as SUCCESS, not a failure to find anything."),
            ["appreciation_test"] = new ConsoleCommandDoc("[name]", "Plants a synthetic QuestDoneForThem appreciation on the NPC (bypassing the real source pipelines) so the prompt/console/encyclopedia loop can be validated without seeding a real gift, payment, quest, or divorce. Still goes through the real TryPlant gate (anti-noise guardrail, the per-holder cap), so it can legitimately refuse."),
            ["appreciations"] = new ConsoleCommandDoc("[name]", "Everything a character is grateful to you for, including what they have never said aloud: what earned it, how warmly it still counts today, and whether a newer grievance has soured it. Reading it changes nothing."),
            ["arrange_marriage"] = new ConsoleCommandDoc("<yourKin> <theirKin> [npc]", "The MATCHMAKER test path: weds one of YOUR clan's unwed kin to a noble of ANOTHER clan (you are neither spouse), with an authority NPC (the target's clan head or parent, or the target themselves) consenting. Drives the real arrange_marriage action through the bridge, so it runs the SAME guards the LLM path uses: engine legality (MarriageModel), the NPC's authority, and the consent policy. npc defaults to the open conversation, else the target kin's own clan leader. Note: it weds two real NPCs, so use it on a test save."),
            ["assembly_cancel"] = new ConsoleCommandDoc("", "Stands the pending assembly down (slice 1: clears the state)."),
            ["assembly_open"] = new ConsoleCommandDoc("", "Opens the convened assembly as the round-table LLM session (the same call the \"Open the assembly\" settlement-menu option makes), for testing the session directly from the console."),
            ["assembly_status"] = new ConsoleCommandDoc("", "Prints the convened roster and the present/en-route/declined/awaiting tally."),
            ["assembly_summon"] = new ConsoleCommandDoc("[companions|lords|all]", "Convenes an assembly at the current town/castle with the player as host, resolves each invitee's RSVP through the real policy, and reports the roster with the reason and the resulting status."),
            ["assembly_test"] = new ConsoleCommandDoc("[n]", "The fast in-game harness for the SESSION: convenes an assembly at the current town/castle and seats N invitees as PRESENT right now (the last one as an AMBASSADOR envoy), bypassing the travel wait, so you can open the round-table immediately (cr.assembly_open, or the \"Open the assembly\" menu) and exercise the multi-speaker LLM session without staging the convergence by hand. Default N = 3."),
            ["assess_alone"] = new ConsoleCommandDoc("", "The player-alone path, the OFFLINE factual summary with NO LLM call."),
            ["assess_soldier"] = new ConsoleCommandDoc("", "The fallback path with a common soldier (green Tactics; fires the real LLM, prints the counsel + logs the prompt)."),
            ["assess_veteran"] = new ConsoleCommandDoc("", "The companion path with a MASTER-Tactics strategist (fires the real LLM, prints the counsel + logs the prompt)."),
            ["audience"] = new ConsoleCommandDoc("[ask|retire|grievance|lover|gratitude|scheme_warning|ambition] [name]", "ask (or popup): raises the REAL \"X asks for a word\" inquiry instead of opening the chat, so the ACCEPT path is walked exactly as a player walks it, staging included (the path Lordfadooboo and Zinced121212 reported opening nothing; try it inside a town, which is where both of them were). Without it, opens a companion AUDIENCE conversation directly (skips the popup): the companion speaks first, voicing a war-weary retirement (default), a grievance, (lover/affection) confiding they wish to become your discreet secret lover, (gratitude/thanks) thanking you for a specific kindness, (scheme_warning/warn) warning you of a secret plot against you, or (ambition) voicing one of their four bound ambitions. For a retirement, grant it in your own words and the companion emits `retire`; for a lover audience, welcome it and they emit `take_as_secret_lover` (needs adult content on + a bonded, orientation-compatible companion). The gratitude, scheme_warning, and ambition options are FOUND-TOPICS (unlike the other three): they delegate to the real resolver/bookkeeping via CompanionAudienceTopicBehavior. TryForceFireGratitude / TryForceFireSchemeWarning / TryForceFireAmbition and report honestly when this companion currently has no qualifying kindness/plot/ambition to raise. For a granted ambition, the FITTING existing action (dispatch_mission/assign_party_role/appoint_governor/arrange_marriage) fires through the normal pipeline, exactly as it would in any other conversation."),
            ["audience_fire"] = new ConsoleCommandDoc("", "Force-fires the strongest found-topic audience anywhere in the party RIGHT NOW, bypassing the global cooldown (the roll itself has no randomness to skip, a topic either qualifies or it does not) and, unlike the real trigger, works from anywhere, not only on entering a settlement. Opens the SAME popup a real settlement-entry offer would; refusing it costs nothing. Says so when no companion currently has anything worth an audience (silence is the default)."),
            ["audience_topics"] = new ConsoleCommandDoc("[name]", "Found-topic companion audiences (player feedback, Nexus): with no name, lists every companion travelling with you and, for each, which of the eight topics (mission follow-up / companion conflict / practical counsel / callback / rumour report / gratitude / scheme warning / ambition) currently qualifies and why, plus the global cooldown state. With a name, shows that one companion's scan only. Diagnostic only, mutates nothing."),
            ["backstory"] = new ConsoleCommandDoc("[name]", "Shows the backstory and traits you authored for a character in character_overrides.json, so you can confirm your file actually took effect."),
            ["backstory_test"] = new ConsoleCommandDoc("[name]", "Injects a strong NAMED persona (a Kratos-style warrior) as a runtime character override on the named lord (or the current conversation NPC), WITHOUT editing character_overrides.json, and forces custom traits on for the session, so the authored-backstory prompt path is exercised end to end. This reproduces the case the v1.30.6 regression broke: a backstory that names a bold figure but spells out no literal speech quirks. Send a message in chat afterwards, the persona should land forcefully (a low, hard, brutal warrior voice), never Calradian lore about God of War. A session reload restores the file-backed overrides."),
            ["balanceofpower"] = new ConsoleCommandDoc("", "Opens the \"Balance of Power\" panel (the World Almanac dashboard) over the current screen. For visual iteration for now; the leak-free campaign-bar entry comes later. Read-and-close, so a brief open over the map is fine."),
            ["bandit_queen"] = new ConsoleCommandDoc("[solo|collective] [male|female]", "Opens a captive scene with a forced FEMALE bandit chief (intent = spoil / PersonalDesire), to test female-aggressor content (facesitting/smothering, reductive domination) without waiting on the rare female-gang roll. Defaults: solo, and a MALE player (the classic woman-dominates-a-man dynamic); pass 'female' for a woman-on-woman scene. The captor's portrait is left blank rather than show a male troop face on a woman. Requires Hardcore."),
            ["bandit_scene"] = new ConsoleCommandDoc("[extortion|intimidation|revenge|spoil] [female|male] [solo|collective]", "Conjures a SYNTHETIC brigand captor (no real hero needed) and opens a captive scene: tests the bandit-captivity path without being captured. Default intent: extortion. 'spoil' = the sexual CNC intent (Hardcore). female|male overrides player gender. 'collective' = the chief's men join in (group aggression). Default: solo."),
            ["bargain"] = new ConsoleCommandDoc("[name]", "Reports whether an NPC may offer the female player the intimacy-as-currency bargain (Phase 3)."),
            ["bargain_items"] = new ConsoleCommandDoc("[name]", "Seeds a DeliverItems→JoinParty bargain on a recruitable wanderer, so the pay-in-goods flow (bag icon → multi-select → bridge settles, the wanderer joins) can be tested without waiting for the LLM to offer it. The required value is the game-side floor (twice the vanilla hiring price). Open a conversation with the wanderer first (or pass a name), then click the bag and hand over goods."),
            ["bargain_leverage"] = new ConsoleCommandDoc("[name]", "Marks an NPC as already holding leverage, to test the escalation prompt."),
            ["bargain_marriage"] = new ConsoleCommandDoc("[name]", "Seeds a marriage_consent bargain on a clan head (or a parent): a deed (clear bandits near a village) conditions the blessing for the player to marry one of their eligible kin. Tests the full A.2b path without the LLM: then cr.quest_done + cr.quest_complete → the blessing is recorded; verify with cr.marriage_status [spouse]."),
            ["bastard_blackmail"] = new ConsoleCommandDoc("[name]", "Reports whether an NPC holds a bastard secret over the player (she is the mother of a still-concealed bastard of yours) and, if so, the gold she could demand for silence. Diagnostic only. Tag one first with cr.bastard_tag if testing without a real birth."),
            ["bastard_check"] = new ConsoleCommandDoc("<motherName> <fatherName>", "Read-only diagnostic for the bastards prestige gate ([[project-bastards]]): maps both heroes' clans to a prestige score and prints whether a grown bastard would press a claim on the FATHER's clan or follow the MOTHER's grander dynasty, plus the discovery risk for a few knower counts. Mutates nothing. The last token is the father; everything before it is the mother's name."),
            ["bastard_claim"] = new ConsoleCommandDoc("[name]", "Resolves a grown bastard's claim against your house using the real prestige gate (maternal house vs yours) and applies it: a lesser/equal maternal house presses a claim (hostility + scandal); a grander one follows the mother's dynasty. Tests the coming-of-age path."),
            ["bastard_demand"] = new ConsoleCommandDoc("[name]", "Force-raise a blackmail demand over the named tracked bastard (testing the pay/leak loop)."),
            ["bastard_mother"] = new ConsoleCommandDoc("[name]", "Shows how an NPC would behave as the mother of the player's bastard, from her traits + regard: blackmail (mercenary), longing, resentful, or a pragmatic plea for keep."),
            ["bastard_pay"] = new ConsoleCommandDoc("[name]", "Pay an NPC's blackmail demands for her silence (gold to her, a grace period bought)."),
            ["bastard_season"] = new ConsoleCommandDoc("", "Runs the seasonal discovery evaluation now (testing, skips waiting a season)."),
            ["bastard_tag"] = new ConsoleCommandDoc("[name]", "Force-tag a hero as a concealed player bastard (testing, no birth needed)."),
            ["bastards"] = new ConsoleCommandDoc("", "Lists the player's tracked bastards: name, hidden/discovered, age, and the per-season discovery chance at that age. Diagnostic only."),
            ["captor_scene"] = new ConsoleCommandDoc("[interrogation|domination|torture|...] [name]", "Opens a PLAYER-AS-CAPTOR scene: the named NPC (or the conversation NPC) is YOUR prisoner and you drive the scene; they react as a captive of their nature. Forces the framing for testing (the NPC need not truly be your prisoner). Non-Hardcore = a tense confrontation; Hardcore unlocks the explicit CNC layer."),
            ["duel_take_field"] = new ConsoleCommandDoc("", "With a conversation open: you call the character out and they take it up, then close the chat with \"Take the field\". The very road a real challenge takes, without their answer, to reproduce a crash on taking the field (Thoragoros1)."),
            ["capture"] = new ConsoleCommandDoc("[name]", "Takes the given lord prisoner into your party: a shortcut so you can test the prisoner freedom-bargain without winning a battle. Imprison them in a fief's dungeon (or keep them in your party) and speak with them: a captive lord may then bargain for their release."),
            ["chat_screen"] = new ConsoleCommandDoc("[on|off]", "Toggles how the chat is hosted (applies to the NEXT chat opened). on = pushed screen: the map is suspended (no VRAM leak) and other screens/menus take focus natively. off = overlay (original): the map stays live behind the chat, but input is grabbed and the naval map leaks VRAM. Flip it to compare the two head to head without restarting."),
            ["chronicle"] = new ConsoleCommandDoc("", "Renders the player's chronicle (their recorded deeds, in chronicler voice) to the console and writes it to CalradiaRemembers_chronicle.log. Phase-1 test path for the world-event store + templated chronicle before the in-game illuminated viewer exists."),
            ["chronicle_illuminate"] = new ConsoleCommandDoc("", "Runs the optional LLM pass that rewrites the chronicle into flowing chronicler prose (style editable in ModuleData/chronicle_style.txt). Async: reopen the viewer once done."),
            ["chronicle_open"] = new ConsoleCommandDoc("", "Opens the illuminated chronicle of your campaign."),
            ["chronicle_rewrite"] = new ConsoleCommandDoc("", "Redo the whole illuminated chronicle (e.g. after editing the style file)."),
            ["close_relationship"] = new ConsoleCommandDoc("[name]", "Open relationship (Inc 3b-b) dev command: forces the named committed partner (or the conversation NPC) through the REAL bridge close_relationship action, revoking the open terms so she takes no new lovers (an existing lover, if any, is left in place: use cr.end_affair to end the current affair). Reports the outcome, including the refusal reason when the target is not a committed partner or holds no open terms."),
            ["commitments"] = new ConsoleCommandDoc("[name]", "Lists any commitments still tracked from an older save (before 2026-08-22, when an NPC's vow stopped being a tracked quest and became a plain memory). On a current campaign this is always empty; a vow now shows up under cr.memory on the NPC who made it. Diagnostic only, mutates nothing."),
            ["companion_scene"] = new ConsoleCommandDoc("[torment|assault|coerce] [victim:Name] [captorName]", "Opens a COMPANION-VICTIM captive scene: the captor works on one of your companions while you are made to watch (torment / assault) or are forced to act (coerce). Forces PlayerStatus = Captive so the rules land without a real capture. Hardcore unlocks the explicit layer; otherwise it stays a tense scene. - victim: a companion-name fragment; defaults to the first companion of your clan, else \"your companion\". - captorName: captor name fragment (defaults to the current conversation NPC)."),
            ["compress"] = new ConsoleCommandDoc("[name]", "Folds a character's older memories into a shorter background straight away, rather than waiting for the daily pass. A first meeting, the recent events and every grave moment are always kept."),
            ["council"] = new ConsoleCommandDoc("[companions|party|family|lords|war|parley <faction>]", "Calls a council. With NOTHING after it, opens the same chooser the \"Hold a council\" button on the map bar opens: every council listed with how many it would seat, and a Cancel - so this is the full replacement if another mod's own bar button has displaced ours. Name one directly to skip the chooser: companions, party, family or lords for your own house, war for the other clan leaders of your kingdom, or parley followed by a faction name to sit down with an enemy."),
            ["council_test"] = new ConsoleCommandDoc("[n|off]", "Assembly spike (2026-07-20): validates the SINGLE-CALL multi-speaker council model without hiring anyone. Open a chat with ANY NPC, run this, and it seats N members (default 3, real lords by clan tier, synthetic fallback) around that host and arms CouncilTurnsForced. Then every message you send is ONE LLM call that yields the host's reply PLUS a [WITNESS_REACTION] from each seated member who speaks or gestures (others stay silent). This is Gabriel's whole-table model, distinct from cr.roundtable (which runs the per-NPC LAP). 'off' disarms it."),
            ["courier"] = new ConsoleCommandDoc("[name]", "Dispatches a test letter from that character and spawns the visible courier party carrying it, so the ride across the map can be watched."),
            ["courier_slow"] = new ConsoleCommandDoc("[name]", "Like cr.courier but spawns a SLOW, engageable courier (speed 2, does not avoid hostiles) so bandit interception and the [COURIER] destroyed path can actually be observed: the normal fast courier almost always outruns threats."),
            ["courier_test"] = new ConsoleCommandDoc("", "Cr.courier [name] Dispatches a test letter to the given NPC immediately, spawning the visible courier party. Use to watch the courier travel the map, be intercepted, or deliver: without going through the compose window. cr.courier_test Spawns a TEST courier from the named settlement's GATE, riding to the player with a stamped test letter. Built for a player validating the gate-spawn fix across towns / ports / castles: if the courier appears outside the walls and rides out, the spawn is good; if it sits frozen, report the settlement. The letter delivers normally on arrival (or is waylaid like any courier on the road)."),
            ["courier_waylay"] = new ConsoleCommandDoc("[name]", "Dispatches a courier and immediately waylays it (as a catching bandit band would), so the loss handling and the \"Send again\" Resend prompt can be seen on demand without chasing anything on the map."),
            ["couriers"] = new ConsoleCommandDoc("", "Lists every in-flight courier: what it carries, its position, food, and how long it has sat still. Robustness batch (ROADMAP 2026-07-20): reads a player report of a wandering courier off the console."),
            ["couriers_recall"] = new ConsoleCommandDoc("", "Recalls every in-flight courier: parties despawn, and each letter reverts to date-based delivery so nothing is lost. The support valve for \"a courier is stuck / wandering\" reports."),
            ["courtship_trial"] = new ConsoleCommandDoc("[status|start|pass|clear] [name]", "Courtship trial (a marriage prospect who agrees to wed BUT first rides at the player's side to be tested). Lets the whole 42-day arc be verified in seconds instead of waiting two in-game seasons. - status: list every tracked trial (start day, passed, whether they accompany the player now). - start [name]: begin a trial for the named prospect today (as if they had just begun accompanying). - pass [name]: force-complete the trial NOW through the real evaluation path: latches the passed flag AND queues her marriage-acceptance letter, so the marriage gate opens on next speaking. - clear [name]: forget any trial for the named prospect."),
            ["crc_scene"] = new ConsoleCommandDoc("[female|male] [solo|collective] [name]", "Opens a captive-encounter chat immediately, forcing PlayerStatus = Captive so Section B (CNC rules) lands in the prompt: without the player actually being a prisoner. Requires Hardcore adult level for the CNC rules to appear. - female|male: override the player gender for this scene (test the other path) - solo|collective: private scene, or a collective scene with soldier witnesses - name: captor name fragment (defaults to the current conversation NPC)"),
            ["crc_scene_staged"] = new ConsoleCommandDoc("[female|male] [solo|collective] [intent] [name]", "Like cr.crc_scene, but STAGES the encounter as a 3D conversation scene (via ChatSceneStager) instead of a bare overlay on the world map: the VRAM-crash fix. Starts a conversation with the captor, then opens the captive chat over the loaded scene. Watch [VRAM]: it should stay flat (no naval map behind)."),
            ["declare_war_quest"] = new ConsoleCommandDoc("[name]", "Seeds a declare_war bargain on the given NPC, targeting the first kingdom you can still declare war on (not your own, not already at war). Then declare war on it (kingdom screen): the deed is stamped done by the WarDeclared event, and the NPC pays out when you report back."),
            ["deed_heard"] = new ConsoleCommandDoc("[name]", "Seeds a notable deed of the PLAYER's that WOUNDS the named (or talked-to) NPC's own faction, then echoes what that NPC would now have heard of you: the influence-loop test path without having to win a real siege. Open a conversation with them afterward to see it colour their tone."),
            ["deliver_prisoner"] = new ConsoleCommandDoc("[name]", "Seeds a deliver_prisoner bargain on the given NPC targeting the first LORD you currently hold (case a: an immediate hand-over). Then, in conversation with that NPC, offer to deliver them: the NPC emits give_prisoner, the captive is transferred, and the reward (500g/+5) is paid. Hold a lord prisoner first. (Case b: capture-and-deliver: arises in real play.)"),
            ["discover_forget"] = new ConsoleCommandDoc("<index> [name]", "Removes the discovered trait at the given 0-based index (see cr.discoveries). The repair path for a player report (Nexus): a profile already carrying a discovery about the PLAYER instead of the NPC can be cleaned up entry-by-entry without wiping the rest."),
            ["discover_forget_all"] = new ConsoleCommandDoc("[name]", "Clears every discovered trait recorded on an NPC's profile. Use when a profile has accumulated enough polluted entries that clearing individually is not worth it."),
            ["discover_test"] = new ConsoleCommandDoc("[name]", "Injects 3 PLACEHOLDER discoveries into the NPC's profile so the encyclopedia discovery section can be validated without playing through a conversation. These are fixed test strings (gender-adapted), NOT real observations about the character: real discoveries are made in conversation. Renamed from cr.discover after a tester ran it on three NPCs, got identical \"She…\" lines on King Derthert, and reasonably concluded the discovery system was broken. Safe to call repeatedly: deduplicated by key."),
            ["discoveries"] = new ConsoleCommandDoc("[name]", "Lists what you have learned about a character in conversation, numbered. If one of them is wrong, cr.discover_forget removes it by number."),
            ["divorce"] = new ConsoleCommandDoc("[name]", "Seeds an estrangement process by dispatching end_marriage through the REAL bridge.ExecuteAction path (the same one a conversation uses), so eligibility is genuinely re-validated. Use cr.divorce_info first to check the gates."),
            ["divorce_info"] = new ConsoleCommandDoc("[name]", "Eligibility (+ the first failing gate), the live facts DivorcePolicy reasons over, and any active estrangement process for the NPC. Read-only."),
            ["divorce_setup"] = new ConsoleCommandDoc("[name]", "Stages a divorcible scenario on an NPC so the feature can be tested even from a campaign where no one you know is unhappily wed: if the NPC is single they are married off to a relocatable partner, then the two eligibility gates are forced (an unhappy marriage + a strong bond with you). Does NOT start the estrangement; run cr.divorce afterward. Mutates the save."),
            ["leave_house_check"] = new ConsoleCommandDoc("[name]", "Read-only: what stands between the player and leaving their house for this ruler who heads hers (the first bar, the heir, each live fact). Gabriel, 26/10/2026."),
            ["give_her_all"] = new ConsoleCommandDoc("[name]", "IRREVERSIBLE, for a throwaway save: the second road (Gabriel, 26/10/2026), no popup. You keep your character and family; she receives your towns, castles, gold and any realm you rule; your house joins her realm, your influence is given back; you wed, each keeping your own house; she pays a season of your house's wages; her people's rivals may declare war."),
            ["leave_house"] = new ConsoleCommandDoc("[name]", "IRREVERSIBLE, for a throwaway save: runs the REAL hand-over now, no popup. The heir takes the house and becomes the played character; the old character weds the ruler and joins her house. Refuses with the bar when the road is not open."),
            ["divorce_tick"] = new ConsoleCommandDoc("", "Runs one day's advance for every active estrangement process now (testing, skips waiting on the real daily tick)."),
            ["dress"] = new ConsoleCommandDoc("<item name fragment>", "Test aid for the captive re-dress feature: equips a matching GARMENT on a held prisoner's BATTLE set (the set the captor scene renders), so the visual can be confirmed. Targets the NPC currently in conversation, else the first female prisoner in the party. Conversation agents do not refresh live, so (re)stage the captive scene AFTER running this to see her wearing it. Never equips a weapon."),
            ["tale_fight_spike"] = new ConsoleCommandDoc("[size]", "SPIKE (09/10/2026): can a tale's last fight be fought by the player and the heroes riding with him only, not the whole army? Spawns a band of the region's bandits (default 6) beside you. Click it: the encounter menu offers 'Fight with those beside you (spike)', which opens the game's own hideout battle on that map battle with you and your companions only. Every step logs a [SPIKE] line, including how the map battle ends."),
            ["duel"] = new ConsoleCommandDoc("[name]", "Stages the REAL non-lethal duel (not the spike): stand on the open map and cross blades with the named lord (or the conversation NPC, or any nearby lord). The two spawn a clear distance apart and close in; the loser is knocked UNCONSCIOUS, never killed; the winner is reported when it ends. This is Inc 1's mission only, the stakes/relation/world-event wiring rides the reported outcome."),
            ["duel_arm"] = new ConsoleCommandDoc("[name] [npc|player]", "Arms DuelCoordinator directly, the same way the chat handler does, without going through the LLM: stages a duel against the named lord (or the conversation NPC, or any nearby lord) once you close whatever window is open and no mission is running. The VENUE is resolved from where you stand, exactly as the real path resolves it: inside a town it stages in the town centre, on the open map it stages a wilderness field, and at sea it refuses. The second argument picks who issued the challenge: \"npc\" (the default) means the NPC called YOU out, so once the map is live you are shown the accept/refuse inquiry; \"player\" means you called them out and they have already accepted (the chat's own acceptance policy already ran), so the duel launches with no prompt. Close any window and watch: this is how the coordinator's deferred launch and the inquiry path are tested without a live LLM turn."),
            ["duel_challenge"] = new ConsoleCommandDoc("[rival] [lady]", "The interactive courtship challenge: a rival presents his demand and you ANSWER it. Accept to fight the duel (its outcome then applies as cr.duel_courtship does); DECLINE to walk away, which costs you renown before the challenge AND the lady's regard (a man who will not fight for her is judged worse than one who fought and lost). This is the accept/refuse core of Inc B2; the LLM chat intro (the rival announcing it in his own voice) and the autonomous approach are the remaining pieces."),
            ["duel_courtship"] = new ConsoleCommandDoc("[rival] [lady]", "Stages a COURTSHIP-RIVALRY duel and applies its full consequence: on top of the generic renown/stance, the courted lady's attraction toward you swings (win -> admiration, lose -> doubt), and a world-event records it so she learns of an outcome she did not witness. Resolves the rival from the first name (or a nearby lord) and the lady from the second (or the first female hero with a profile). Watch the log for \"attraction toward you: X -> Y\"."),
            ["duel_here"] = new ConsoleCommandDoc("[name]", "WILDERNESS SPIKE. Stand on the open map (not inside a settlement) and run this to open a throwaway field-combat scene against the named lord (or the conversation NPC, or any nearby lord), spawn the two fighters, hold it for about half a minute, and return to the map. It measures VRAM before and after in the log under [DUELSPIKE], to prove whether a field scene opens and closes cleanly with no render-target leak. This is plumbing only: the real non-lethal duel (witnesses, stakes, the challenge_duel action) is the rest of Inc 1, not this."),
            ["duel_town"] = new ConsoleCommandDoc("[name]", "Stages the TOWN duel directly, bypassing DuelCoordinator entirely: stand inside a town (on the town menu, not in a scene) and this opens the town-centre scene, injects the named lord among the crowd, and starts the non-lethal duel. Use it to isolate the SCENE staging (does he spawn, does the fight start, does the knockout return you to the town) from the deferral and the inquiry, which cr.duel_arm covers. Watch the log for the \"[DUEL] injected\" and \"[DUEL] town duel started\" lines."),
            ["end_affair"] = new ConsoleCommandDoc("[name]", "Open relationship (Inc 3b-b) dev command: forces the named partner (or the conversation NPC) through the REAL bridge end_affair action, ending her current affair (clears TakenLoverId and resets every affair-tracking field, records an ended-affair memory). Reports the outcome, including the refusal reason when the partner has no taken lover to give up."),
            ["end_own_marriage"] = new ConsoleCommandDoc("", "Dispatches end_own_marriage through the REAL bridge.ExecuteAction path (the same one a conversation uses) against the player's own current spouse. Says so plainly when the player is unmarried, rather than mis-reporting the action as broken."),
            ["escape_force"] = new ConsoleCommandDoc("", "Makes the NEXT escape attempt in a captive scene succeed, so the full escape flow (constrained captor reaction → freeing on scene close) can be tested despite the 10% natural chance. Then, in the scene, type an escape attempt (e.g. \"I lunge for the door and bolt\") so the LLM emits escape_attempt."),
            ["escape_test"] = new ConsoleCommandDoc("[n]", "Captivity-escape spike (W1): stand on the OPEN map and stage the 1-vs-N escape scene, you UNARMED in civilian clothes against n aggressors (default 2, clamp 1..3) each with a Knobbed Club. Knock them all down OR run to the edge of the scene to \"escape\"; get knocked out and you are \"recaptured\". Everyone falls unconscious, never dies. This is plumbing only: the real release / lost gear+horse / nemesis memory ride the reported outcome (shown here as a message), not yet wired to captivity."),
            ["escort_channel"] = new ConsoleCommandDoc("[name]", "Toggles and reports the ARMED ESCORT flag on a correspondent's whole thread (NpcProfile.EscortedChannel). An escorted thread's couriers (both directions, all later legs) ride immune to bandit interception, so this exercises the immunity without paying the tavern premium or waiting for a real dispatch."),
            ["execute_prisoner"] = new ConsoleCommandDoc("[name]", "Nemesis pillar increment 2 (R2 execute, chat-driven entry point): exercises the execute_prisoner bridge action directly, the same call BannerlordGameStateBridge.ExecuteAction makes when the LLM emits it during a player-as-captor scene (NemesisPrisonerDialogFlow / cr.nemesis_captor_scene). Targets the named hero, else the tracked nemesis currently held prisoner (see cr.nemesis), else the current conversation partner. The bridge re-validates custody itself, so this is not a forced test framing: the target must be a REAL prisoner of the player."),
            ["feed_test"] = new ConsoleCommandDoc("[summary]", "Exercises the Extension Surface (Volet A): feeds a sample external world fact through Feed.Record, the same door a third-party mod uses, tagged with your realm and the nearest settlement at magnitude 60. Reports the result, how far and how long the news will carry, and the id to check with cr.heard."),
            ["fief_audience"] = new ConsoleCommandDoc("[grudge|appreciationowed|nemesisbounty|heardofdeed] [name]", "Forces the fief-audience \"may I have a word\" popup for the named partyless NPC standing in a settlement (ladies, notables, a garrisoned lord with no field party), the settlement-entry counterpart to cr.intercept, bypassing the pacing roll and the per-NPC cooldown to test the Accept/Decline popup without waiting for a real entry. The trigger defaults to HeardOfDeed when omitted; territorialpatrol is road-only (FiefAudiencePolicy.IsFiefValid) and is never fief-valid however it is forced."),
            ["forget"] = new ConsoleCommandDoc("<index> [name]", "Makes a character forget one thing. Take the number from cr.memory."),
            ["forget_all"] = new ConsoleCommandDoc("[name]", "Wipes everything a character remembers of you and leaves them a stranger again. There is no undo, and the letters they have already sent you are not affected."),
            ["gear_recover"] = new ConsoleCommandDoc("[name]", "Forces CaptiveGearBehavior.RecoverAndGrantToPlayer for the resolved hero right now (the same call the real \"holder dies/is captured\" hooks make): the WHOLE stock (worn + inventory) is granted to the player's own roster and the ledger entry is cleared. A no-op, reported, when the holder keeps nothing."),
            ["gear_stock"] = new ConsoleCommandDoc("[name]", "With a name: reports that hero's held-gear stock (every item, tier/value, and which are currently \"worn\" per CaptiveGearStockPolicy.SelectWorn). Without a name: dev-truth dump of EVERY holder currently on the ledger. Read-only."),
            ["gear_test"] = new ConsoleCommandDoc("[name]", "Force-runs the REAL Fled transfer (CaptiveGearBehavior.TransferPlayerGearTo) against the resolved hero, using the player's CURRENT battle equipment, without staging the escape mission. Equip whatever you want to test with first. Follow with cr.gear_stock to see it accumulate, or cr.gear_recover to test getting it back."),
            ["geo"] = new ConsoleCommandDoc("[something you might say about a place]", "Shows what the mod actually tells a character about the land: where they are standing, and the real facts about any settlement your text names. Use it if a character invents where a town sits."),
            ["give_gold"] = new ConsoleCommandDoc("<amount> [name]", "The character hands the player that many denars, through the same path a conversation would use."),
            ["give_prisoner"] = new ConsoleCommandDoc("[name]", "Captures a live lord straight into the player's party as a hero prisoner, so the prisoner-trade UI (the bag's \"A prisoner\" offer) and the buy/sell verbs can be tested without hunting one down in game. With a name fragment it takes that lord; without, the first free non-player-clan lord it finds."),
            ["give_troops"] = new ConsoleCommandDoc("[name]", "Forces give_troops (04/07/2026, the reciprocal of lend_troops) through the REAL bridge.ExecuteAction path (the same one a conversation uses), so eligibility is genuinely re-validated. Reports the underlying facts (relation, the NPC party's strength against the weakened threshold, the player's own spare capacity) first, so a refusal is diagnosable without guessing which gate failed."),
            ["grudge_backfill"] = new ConsoleCommandDoc("", "Force-reruns the one-shot migration scan regardless of the stamped version, reporting how many grudges formed vs were skipped. Idempotent: running it again in the same session forms nothing new (the deterministic holder+source+day id dedups), which this command calls out explicitly so a second run's zero-formed result reads as SUCCESS, not a failure to find anything."),
            ["grudge_execute_kin"] = new ConsoleCommandDoc("[name]", "Force-runs the exact ExecutedKinGrudgeBehavior plant loop against the named hero's close living kin (spouse/parents/children/siblings), as if the player had just had them executed, without actually killing anyone. Goes through the real TryPlant gate for every kin considered, so it can legitimately plant fewer than it considers (anti-noise guardrail, or a full, stronger house)."),
            ["grudge_resolve"] = new ConsoleCommandDoc("[amends|gift <value>|deed] [name]", "Runs TryResolveDominant against the NPC's dominant resolvable live grudge with the given gesture, no LLM involved. Reports the verdict plus the grudge's before/after magnitude, so the resolution engine can be validated deterministically. Defaults to the Amends gesture (giftValue 0) when the gesture argument is omitted or unrecognized."),
            ["grudge_sway_reveal"] = new ConsoleCommandDoc("[name]", "Forces the REAL pending SwayExposureBehavior watch for this NPC (queued by a real in-conversation sway_opinion against them) to reveal now, bypassing only the awareness TIMING (never the SwayExposedGrudge rule nor TryPlant's own guardrails). Reports when no watch is pending."),
            ["grudge_sway_test"] = new ConsoleCommandDoc("[name]", "Plants a synthetic SwayExposed grudge on the NPC (bypassing the real sway_opinion + rumour-reveal pipeline) via the real Tier2GrudgeRules.SwayExposedGrudge rule and TryPlant gate, mirroring cr.grudge_test's shape. To exercise the REAL delayed reveal pipeline instead (sway_opinion -> Rivalry rumour -> SwayExposureBehavior -> awareness -> plant), sway a real target in conversation (stance=against) then run cr.grudge_sway_reveal."),
            ["grudge_terms"] = new ConsoleCommandDoc("[name]", "Runs the grudge_terms reveal deterministically (no LLM), via the exact same Execute path an in-conversation [ACTION] grudge_terms would take, against the NPC's dominant known, resolvable grudge whose resolution hint is not yet discovered. Reports which grudge's hint was revealed, or that none qualified (already discovered, unresolvable, unknown to the player, or no grudge at all)."),
            ["grudge_test"] = new ConsoleCommandDoc("[name]", "Plants a synthetic FailedQuest grudge on the NPC (bypassing the real source pipelines) so the prompt/console loop can be validated without seeding a real quest, scheme, or divorce. Still goes through the real TryPlant gate (anti-noise guardrails, the per-holder cap), so it can legitimately refuse."),
            ["grudge_unblessed_clear"] = new ConsoleCommandDoc("", "Runs the exact GrudgeBehavior.ResolveUnblessedMarriageGrudgesAgainst seam DivorceProcessBehavior and SpouseDivorceDemandBehavior call the moment the player's own marriage dissolves, clearing every live UnblessedMarriage grudge against the player regardless of holder. No NPC argument: this source is only ever aimed at the player, so it resolves everything at once, exactly as a real divorce would."),
            ["grudge_unblessed_test"] = new ConsoleCommandDoc("[name]", "Plants a synthetic UnblessedMarriage grudge on the NPC (bypassing the real MarriageApprovalBehavior wedding pipeline) via the real Tier2GrudgeRules.UnblessedMarriageGrudge rule and TryPlant gate, mirroring cr.grudge_sway_test's shape. To exercise the REAL plant instead, revoke or never grant a blessing (cr.marriage_revoke) then marry the family's kin via cr.marry, and check with cr.grudges."),
            ["grudges"] = new ConsoleCommandDoc("[name]", "Everything a character holds against you, including what they have never let on: what caused it, how deeply it still runs today, how rigid they are about it, and what it would take to mend. Reading it changes nothing."),
            ["happiness"] = new ConsoleCommandDoc("[name]", "Shows a companion's contentment in your service (score + band)."),
            ["happiness_set"] = new ConsoleCommandDoc("<0..100> [name]", "Sets a companion's contentment, to test the bands/encyclopedia line."),
            ["happiness_tick"] = new ConsoleCommandDoc("", "Runs a weekly happiness pass now (idle/loved-one pressure, drift, and any departures)."),
            ["heart_seed"] = new ConsoleCommandDoc("[days_ago] [name] [forced]", "Gives a character a love story with you, begun days_ago days back (120 by default), to see the encyclopedia's Heart and Kindnesses sections: a flirt, a first night and a recent one in their memory, the bond made intimate from the first night, their regard raised to at least +50 (devoted), and the kindness such a night leaves. The nights show at Hardcore only. With 'forced' it records instead that you took them by force while your prisoner, today (your Misdeeds and their Trauma, at Hardcore). A test tool: it stays in the save once saved, and cr.forget_all clears the memories (not the bond nor a forced record)."),
            ["heard"] = new ConsoleCommandDoc("[name] [event-id|all]", "Whether a character has heard the stored world events, and why: the score, each term behind it (magnitude, realm, place, recency, named), how many days they keep it, or which levers would reach them. Nothing is copied into a character's memory, awareness is recomputed at every prompt, so this is the answer. With no id it lists the events fed by other mods; 'all' adds CR's own."),
            ["history_file"] = new ConsoleCommandDoc("", "Writes this campaign's world snapshot for the history editor page (HistoryEditor.html), creates an empty history file when there is none, and prints both paths. The history file holds events of the past, before the campaign began, written by you."),
            ["history_reload"] = new ConsoleCommandDoc("", "Reads this campaign's history file again: its events replace the authored ones in the long-term memory, its starting relations move by what changed since the last load, and what was set aside is written next to it (.history.problems.txt). Also done at every load."),
            ["history"] = new ConsoleCommandDoc("[name]", "The world's long-term memory: the battles, sieges, conquests, executions, lords fallen in battle, marriages, divorces, wars, peaces, risings, discovered schemes and captures that left the news after 42 days but are still remembered. With a name, only what that character would know: what he was in, what befell his kin, his house or his home, and the greatest events of his realm. Reading it changes nothing."),
            ["help"] = new ConsoleCommandDoc("[all|<command>|<text>]", "This. cr.help all lists every command there is, cr.help followed by a command name explains that one in full, and any other text searches the names."),
            ["hire_info"] = new ConsoleCommandDoc("[name]", "Shows whether the NPC is recruitable through conversation (join_party) and the price band: vanilla asking price, negotiation floor (75 %) and cap (125 %). Mirrors the exact eligibility checks the prompt gating and the bridge use."),
            ["hostage_force_breach"] = new ConsoleCommandDoc("[name]", "Forces the give_hostage breach consequence on an active/seeded hostage term: the hostage's house \"breaks faith\" and the hostage becomes the player's prisoner, without staging a real battle. Seed one first with cr.seed_accord hostage <name>."),
            ["impression"] = new ConsoleCommandDoc("[name]", "Prints the \"first impression\" opening disposition CR would inject for a barely-known noble (or the current conversation partner): how their traits and your standing colour their opening tone. Blank means a neutral opening, an own-clan lord, or an already-known NPC (their stance governs)."),
            ["info"] = new ConsoleCommandDoc("[name]", "How you stand with a character: their personal regard for you, whether either of you is the other's prisoner, and how long before an ordinary conversation can raise that regard again."),
            ["intercept"] = new ConsoleCommandDoc("[grudge|appreciationowed|nemesisbounty|territorialpatrol|heardofdeed] [name]", "Forces the named lord (with a party on the map) to ride out and intercept the player, bypassing the eligibility roll, to test the pursuit without waiting for the daily tick. The trigger defaults to HeardOfDeed when omitted (the original behaviour); for grudge/appreciationowed/ nemesisbounty, the lord's REAL grievance/kindness/eligible nemesis against the player is used when one exists on file."),
            ["interpret_test"] = new ConsoleCommandDoc("", "PROSE + INTERPRETER spike: runs three CANNED roleplay-prose samples (each with its EXPECTED tags stated inline) through whatever model is configured in MCM, used here as an ACTION INTERPRETER. For each sample it builds an interpreter prompt via ActionInterpreterPromptBuilder, calls the model one-shot, parses the raw output with the SAME SectionResponseParser the live chat uses, and writes expected-vs-actual to CalradiaRemembers_interpret_test.log so Gabriel can judge interpretation fidelity by reading. This changes NOTHING in the live chat pipeline: it is a real-LLM bench, deliberately NOT part of cr.testall. Set an interpreter model (e.g. Grok) in MCM, run this, then read the log."),
            ["jealousy"] = new ConsoleCommandDoc("[flirt|intimacy|marriage] [name]", "Resolves and immediately fires a jealousy reaction as if the player had just made a romantic advance of that tier (default flirt) toward the named NPC (or the current conversation partner). Bypasses the witness/probability/cooldown gates so the resolution and consequence are testable without building a full romance: it prints the inferred jealous party and applies the grudge + grievance memory + a threatening letter."),
            ["jealousy_comp"] = new ConsoleCommandDoc("", "Reports the player's current partner household (native spouse + committed consorts) with each one's culture, sharing-tolerance and how long since they were last attended to, then forces one competition pass so the v1.5 ongoing-rivalry loop can be tested without waiting."),
            ["journal_check"] = new ConsoleCommandDoc("", "Diagnostic: prints how many CalradiaRemembers quests are registered in Campaign.Current.QuestManager and lists their StringIds. Use to verify that cr.quest actually created a QuestBase mirror in the journal."),
            ["journey_recall"] = new ConsoleCommandDoc("", "Recalls EVERY away companion immediately: the conversation/console path (abandon the errand and rejoin the party now). The safety net for the AI-Influence bug: a real homecoming, never a promise."),
            ["acts"] = new ConsoleCommandDoc("[name]", "Lists the gestures a character particularly loves in bed, the ones they dislike, and which of them you have learned by living them. Said to the character at Hardcore only; a character met before 2.7.21 is given theirs here or at the next conversation."),
            ["act"] = new ConsoleCommandDoc("<gesture> [performed|proposed] [name]", "Plays one gesture through the real path, as if it had been read in the exchange: a disliked gesture performed costs the character's personal regard and leaves a memory (once a day per gesture), one only proposed costs nothing, a loved one found the first time warms them a little; either way the taste is learned. Needs Hardcore and a character who would permit intimacy. See cr.acts for the gesture names."),
            ["kinks"] = new ConsoleCommandDoc("[name]", "Lists a character's kinks and the names you may add or remove with cr.add_kink and cr.remove_kink. Needs the Adult Content level set high enough to matter."),
            ["letter"] = new ConsoleCommandDoc("[name]", "Queues a test letter from the NPC with DeliveryDay = today so it shows up on the next daily tick (or immediately via cr.letter_deliver). Uses RomanticCorrespondence as the reason so personality is exercised."),
            ["letter_compose"] = new ConsoleCommandDoc("[name]", "Opens the writing desk to send a letter to a character, wherever they are."),
            ["letter_glyphs"] = new ConsoleCommandDoc("[blocks] [name]", "Delivers a letter loaded with the characters a real LLM letter can contain, which an ASCII test letter never exercises: CJK, Cyrillic, Greek, accents, curly quotes and dashes, right-to-left Arabic, symbols, and emoji (astral-plane surrogate pairs). Written for the crash report of 2026-09-06, after Gabriel's own log showed the model returning a whole letter summary in Chinese: a glyph missing from the font atlas would explain BOTH reported symptoms, the crash while scrolling and the campaign font turning bolder (a fallback face). Blocks are added hardest-last, so passing a count BISECTS which script is fatal: cr.letter_glyphs 1 is Chinese only, 8 is everything."),
            ["letter_history"] = new ConsoleCommandDoc("[exchanges|clear] [name]", "Seeds a long correspondence ARCHIVE with an NPC and opens the letter book on it, so the LEFT page's scrollbar (the thread of past letters) can actually be exercised. The letter body has its own scrollbar, tested by cr.letter_long; this is the other one, and the crash report of 2026-09-06 does not say which. Each exchange is an incoming letter plus the player's reply, so it yields two thread entries. WRITES TO THE SAVE: every seeded letter is tagged, and \"cr.letter_history clear\" removes exactly those."),
            ["letter_long"] = new ConsoleCommandDoc("[paragraphs] [name]", "Delivers a test letter whose body is long enough to actually SCROLL (default 12 paragraphs), through the same real delivery path as cr.letter_read. Written for the crash report of 2026-09-06 (a player crashed as soon as they scrolled a letter): an ordinary test letter is one line, so the scroll path was never exercised. Pair it with a high UI Scale, which is what engages the parchment's fit zoom."),
            ["letter_offer"] = new ConsoleCommandDoc("<prisoner|service> [name]", "Opens a synthetic OFFER letter in read mode so the Accept / Decline affordance can be exercised without waiting for the mailbox. \"prisoner\": a lord (the named one, else any solvent lord) offers to buy the FIRST hero prisoner you hold, and Accept settles the REAL ransom (gold + transfer). \"service\": the named lord offers you a place in their service, and Accept warms the bond (a light hook, no allegiance change)."),
            ["letter_read"] = new ConsoleCommandDoc("[name]", "Has a character write to you now and opens the letter, so you can read and answer it without waiting for a courier to cross the map."),
            ["letter_reply"] = new ConsoleCommandDoc("[name]", "Opens the parchment courier window straight in REPLY mode with a synthetic received letter: write a reply and seal it. The send seals + queues the NPC's answer + closes synchronously (no inline LLM call), the pattern that ended the close-on-reply hang and crash."),
            ["letter_tidings"] = new ConsoleCommandDoc("[name]", "Runs the realm-tidings evaluation for one writer NOW: scores the world events they plausibly know, picks the most worth-telling one they have not already relayed, and enqueues an unbidden \"news of the realm\" letter into the mailbox (competing in the normal budget). Reports which event was chosen, or why none was. Seed some conditions first with cr.worldcond if the store is empty."),
            ["letter_where"] = new ConsoleCommandDoc("[name]", "Whereabouts grounding test (player-reported bug: a correspondent kept writing as if still in a town both parties had left). Plants a memory placing the last meeting in a DIFFERENT settlement than where the NPC currently is, then generates a letter and logs, to CalradiaRemembers.log: the planted (stale) location, the NPC's REAL resolved whereabouts, and the full letter body. The letter should ground itself to the real location (or the field), never to the planted town."),
            ["letters"] = new ConsoleCommandDoc("[name]", "Fills in a short exchange of past letters with a character, both directions and properly dated, and opens the archive on it."),
            ["loot_stock"] = new ConsoleCommandDoc("", "Dev-truth dump of the SCATTERED-loot ledger (AUDIT-NEMESIS M1): every piece of the player's gear scattered among bandit bands after a fled bandit escape, its culture, and the day it was lost. Recovery is per-battle: beat a band of a matching culture and one piece has a chance to return. Read-only. (Distinct from cr.gear_stock, which is the LORD holder ledger.)"),
            ["lore_status"] = new ConsoleCommandDoc("", "On-demand diagnosis for character_overrides.json, independent of the \"Enable Logging\" MCM toggle (that switch gates ModLog.Info/Error, so a player editing the file with logging off otherwise gets zero feedback). Reports whether custom traits are on, which path the loader looked at and whether it existed, how many entries loaded and the last parse error (if any), and for each authored entry whether it currently resolves to a live hero, so a typo in \"hero\" or \"id\" is visible immediately."),
            ["lover_child"] = new ConsoleCommandDoc("[name]", "Open relationship (Inc 3c) dev command: forces the named partner (or the conversation NPC), who must already carry a taken lover (use cr.take_lover first) and be fertile, to conceive a child BY HER LOVER now, bypassing only the per-tryst conception roll. Runs the REAL path: the child's father is the lover (never the player), the pregnancy is registered as a lover-child so it lands in the LOVER's line at birth, and a SECRET affair is revealed by the pregnancy. Reports the confirmed father (read back out of the engine's own pregnancy list), the intended clan the child will join, and the discovery state. Refuses with a reason, never a silent no-op."),
            ["mapsuspend"] = new ConsoleCommandDoc("[on|off]", "Toggles the fix that stops the host map scene from rendering behind the chat overlay (default ON). Turn it OFF to reproduce the VRAM climb, ON to confirm it goes flat. Applies to the NEXT chat opened."),
            ["marriage_approve"] = new ConsoleCommandDoc("[name]", "Seeds the family's blessing for the player to marry the named hero (approver = their clan leader). Then marry them (cr.marry or in-game) to see the family warm to you instead of turning hostile."),
            ["marriage_revoke"] = new ConsoleCommandDoc("[name]", "Removes a seeded blessing for the named hero."),
            ["marriage_status"] = new ConsoleCommandDoc("[name]", "Reports whether the family has blessed a match with the named hero, plus the basic eligibility the marriage path will check (spouse single, player single)."),
            ["marry"] = new ConsoleCommandDoc("[name]", "Forces a native marriage between the player and the named hero so the consequence resolver (warm/hostile family) can be tested end to end. Pair with cr.marriage_approve / cr.marriage_revoke to test both outcomes. Also the player's REPAIR PATH for the marriage-memory bug (Nexus, v1.31.4): a chat that narrated and recorded a wedding ExecuteMarry actually refused can be sealed for real here, deliberately bypassing the guards cr.marry_check reports on (run that first to see WHY the chat version never happened)."),
            ["marry_check"] = new ConsoleCommandDoc("[name]", "(read-only diagnostic). Runs every guard BannerlordGameStateBridge's ExecuteMarry checks, in the SAME order, and reports a pass/fail line for each with the specific blocker named. Mutates nothing. Built after a player report (Nexus, v1.31.4): the chat and letters narrated a complete wedding and recorded it as an [EVENT] (\"Mesui and Huan Yi married under Khuzait law...\"), but the engine never married anyone (cr.marriage_status showed the spouse still free). Either the marry action was never emitted at all, or ExecuteMarry refused it and the model narrated straight over the refusal. This command names exactly WHICH guard blocks a marriage the fiction promised. (The age gap that was the prime suspect in that report is no longer a guard: it was removed 2026-07-21, since a marriage is a contract between two adults.)"),
            ["marry_companion"] = new ConsoleCommandDoc("[name]", "FEASIBILITY PROBE (spike, not a shipped verb). Resolves one of the player's own companions (a name fragment, else the first companion found), evaluates the pure MarryCompanionEligibilityPolicy carve-out on live facts, asks the engine's MarriageModel.IsCoupleSuitableForMarriage , then attempts a real Apply and reports the outcome and the companion's resulting state. Should the engine actually seal the union (it will not for a raw wanderer, but the guard is honest), the marriage is reversed immediately through MarriageDissolutionService so no diagnostic ever leaves the player wed."),
            ["marry_info"] = new ConsoleCommandDoc("[name]", "Reports, gate by gate, whether the player could wed this hero right now and, when they could not, WHICH gate is shut and by how much. Written after a player report (2026-07-23) where a marriage \"happened\" in dialogue and not in law: the mod had no way to answer \"why\", and neither did the player, who had earned the family's blessing through a quest and never learned that the BRIDE's own regard is a separate gate (a quest's relation reward goes to the giver, not to their daughter). Read-only: reports the live state, changes nothing. The sibling of cr.hire_info."),
            ["memory"] = new ConsoleCommandDoc("[name]", "Prints everything a character remembers of you, numbered oldest first. The number in front of each line is what cr.forget takes. With no name, the character you are talking to."),
            ["memory_add"] = new ConsoleCommandDoc("<days_ago> <text> [name]", "Writes a memory into a character's past, so you need not begin every acquaintance as a stranger. The last word is read as a name if it matches one. Example: cr.memory_add 30 We fought side by side at Pendraic. Derthert"),
            ["memory_load"] = new ConsoleCommandDoc("", "Lists the characters carrying the most memories, since those are the ones inflating the prompt, and says whether each is due for compression. Mutates nothing."),
            ["memory_repair_accents"] = new ConsoleCommandDoc("", "Mends every stored memory whose accents the console mangled before 2.6.11 (\"Ã©\" where \"é\" was typed). Touches nothing else: safe on any save, and safe to run twice. Save afterwards to keep it."),
            ["memory_set"] = new ConsoleCommandDoc("<index> <text> [name]", "Rewrites one memory in a character's own words. Take the number from cr.memory."),
            ["mission_return"] = new ConsoleCommandDoc("", "Force-resolves the first in-flight errand NOW and prints the report: the test path so you need not wait the in-game days for the companion to ride there and back."),
            ["missions"] = new ConsoleCommandDoc("", "Lists the errands companions are currently away on, patrols included."),
            ["model"] = new ConsoleCommandDoc("", "Reports which model each part of the mod is talking to, and which of the three in-chat modes (Enhanced, Roleplay, NSFW) is active. Worth checking when a reply is not the quality you expected."),
            ["nemesis"] = new ConsoleCommandDoc("[name]", "No args: lists the persistent nemesis roster (name, band, region, alive, recaptures, bound Hero) and whether the player is currently a nemesis's captive. Dev diagnostic for validating the Nemesis pillar in game: capture by a bandit party should mint/reuse a nemesis and bind a real Hero to him. With a name fragment: also previews the encyclopedia dossier that hero's page would render, via the exact same NemesisDossierFactory.BuildFor the real page calls (discoverability piece, player report SuperGraham339), printing \"(hidden: not yet encountered)\" when the gate would hide it."),
            ["nemesis_bounty"] = new ConsoleCommandDoc("[lord name]", "Nemesis pillar increment 3 (bounty missions test harness): force-offers (and immediately accepts, on the giver's behalf) a bounty on the named lord's own region, minting or reusing a tracked nemesis anchored there via the same MintCaptorFor path the real capture hook uses, so the region-eligibility gate (NemesisBountyPolicy) and the reward math (NemesisBountyRewardPolicy) both run for real, not simulated. Falls back to the first living non-player lord when no name matches."),
            ["nemesis_bounty_complete"] = new ConsoleCommandDoc("[giver name]", "Force-completes the named giver's outstanding nemesis bounty (or the first active one found on any giver, if no name matches): stamps the deed satisfied if not already, then runs the same acknowledge-and-pay path as cr.quest_complete. Tests the report-back/reward leg without a real capture or kill."),
            ["nemesis_captor_scene"] = new ConsoleCommandDoc("[interrogation|desire|domination|torture|training|reward]", "Nemesis pillar increment 2 (R3 test harness): opens a PLAYER-AS-CAPTOR scene against the first tracked nemesis with a bound Hero, the inversion of his earlier captivity of the player. Confirms his existing memory profile (built in increment 1) loads automatically, since the scene keys off his Hero/StringId exactly like cr.captor_scene. Routes through ChatSceneStager.StageCaptorScene (the VRAM-safe staged-conversation path, no live conversation to ride from the console), unlike the real in-game entry point (NemesisPrisonerDialogFlow's hero_main_options line, reached from the party-screen Talk on a held nemesis), which opens directly via ChatManager.OpenForCaptorScene because it already rides a live conversation scene."),
            ["nemesis_execute"] = new ConsoleCommandDoc("[name]", "Nemesis pillar increment 2 (R2 test harness): simulates an EXECUTION of the named tracked nemesis, or the first living one on the roster if no name matches. Runs the exact same NemesisResolutionBehavior.Resolve code path the real HeroKilledEvent hook uses."),
            ["nemesis_kill"] = new ConsoleCommandDoc("[name]", "Nemesis pillar increment 2 (R1 test harness): simulates a BATTLE death (not an execution) of the named tracked nemesis, or the first living one on the roster if no name matches. Runs the exact same NemesisResolutionBehavior.Resolve code path the real HeroKilledEvent hook uses."),
            ["orientation"] = new ConsoleCommandDoc("<straight|bi|gay|lesbian|pan|asexual> [name]", "Changes a character's orientation when the one they were given blocks a romance you wanted. To make it permanent, add it to their entry in character_overrides.json."),
            ["panel_seed"] = new ConsoleCommandDoc("[name]", "Fills every section of the portrait info panel on the named lord (or the conversation NPC) so it can be verified visually: personal regard, a simulated authored backstory (as if from character_overrides.json), three discoveries (including a kink), an appearance description, and a known grudge. Background comes from the vanilla encyclopedia automatically. Left-click the portrait in chat afterwards to check the rendering."),
            ["pledge"] = new ConsoleCommandDoc("[name]", "Seeds a real pledge_against for testing: resolves the target NPC (or the current conversation NPC), picks a kin-safe rival, forces the two into genuine enmity (below PledgeMinAnimosity), then fires the SAME pledge_against action BannerlordGameStateBridge executes from a real conversation: an end-to-end seed, not a reimplementation. Launches the underlying scheme (ForcePlot) and leaves a memory of the vow on the promisor (2026-08-22: a vow is remembered, not tracked as a quest, so there is no journal mirror and no countdown). Check it with cr.memory. **(save)**"),
            ["portrait_id"] = new ConsoleCommandDoc("[name]", "Prints the exact file name to drop in ModuleData/ChatPortraits/ for the current (or named) NPC, since a hero's StringId is opaque otherwise. Also reports whether an image is already found for them."),
            ["portrait_spike"] = new ConsoleCommandDoc("[full\\path\\to\\image.png]", "Loads an image from disk at runtime and shows it in a test overlay. With no argument, reads cr_portrait_test.png from the Bannerlord Documents folder. Close releases the texture."),
            ["portrait_spike_stress"] = new ConsoleCommandDoc("[count] [full\\path]", "Loads and immediately releases the image [count] times (default 50) without showing it, to check VRAM stays flat under repeated runtime texture loads. Watch dedicated GPU memory in Task Manager."),
            ["postduel"] = new ConsoleCommandDoc("[win|loss] [name]", "Stages the POST-DUEL conversation directly, without fighting a duel first, so the resume and the victor/loser register can be inspected in game. \"win\" (the default) opens it as though the PLAYER won (the NPC concedes and may grant a favour); \"loss\" opens it as though the NPC won (they press what they expect). A short synthetic pre-duel exchange is seeded so the replayed bubbles and the LLM continuity are visible. Resolves the named lord, or the conversation NPC, or any nearby lord. Stand on the open map to see it stage a scene (the real flow triggers there right after a fought duel)."),
            ["balance_survey"] = new ConsoleCommandDoc("[on|off|now|report]", "The balance-of-power survey (a measurement before any balancing lever is built). \"on\" records every realm each week (Power Index, strength, towns, castles, villages, wars, allies) and every war, peace, alliance and call to war, into CR_BalanceSurvey_<campaign>.csv in the game's Logs folder; it stays on across saves until \"off\". \"now\" takes one reading. \"report\" reads the file back: who led at the start and the end, the highest share of fiefs any realm reached, how concentrated the map became, and how many wars and alliances turned against the leader. No argument: status and file path."),
            ["powerindex"] = new ConsoleCommandDoc("", "Prints the \"Balance of Power\" Power Index for every living kingdom: the scored ranking with its six pillars, the raw facts each score is drawn from, the key indicators, and the field totals. Use it to sanity-check and tune the formula (in PowerIndexPolicy) against a real campaign before the UI exists. The full report is also written to the log file."),
            ["preg"] = new ConsoleCommandDoc("[name]", "The female PLAYER is the mother; [name] is the father (a lord), else the shared hidden \"Unknown\" father (the faceless-bandit case). cr.preg mother [name]: that NPC is the mother and the player is the father (the bastard path): used to run the in-game SPIKE on which clan the child lands in. Forces a conception (bypasses the 15% roll) so the pregnancy → delivery path can be validated without waiting on a real scene."),
            ["preg_birth"] = new ConsoleCommandDoc("[name|reset]", "Two-phase test that a CR-created pregnancy is actually DELIVERED by the engine (the open question behind pregnancy's Hero.IsPregnant=False). First call ARMS: it force-conceives a fertile female (named, or auto-picked) and records her child count. Advance ~84 days (fast- forward, NO reload: the marker is in memory), then call again to CHECK: a new child = PASS (the IsPregnant flag is cosmetic); 84+ days and none = FAIL (the flag blocks delivery). Pass \"reset\" to re-arm. Not part of cr.testall: a birth cannot resolve inside one command."),
            ["profile_check"] = new ConsoleCommandDoc("[name]", "Checks that a character's profile can be saved and read back, and names the field if it cannot. Worth running if a character's memory seems to vanish between sessions."),
            ["prompt_size"] = new ConsoleCommandDoc("[name]", "Reports the size of the system prompt CR would send for this NPC (characters + a rough token estimate) and whether the \"Compact prompt for small models\" mode is on. Toggle it in Mod Options and re-run to see the reduction: the fix for a small local model that overflows its context and returns nothing."),
            ["prose_interpret_test"] = new ConsoleCommandDoc("[proseModelId]", "Runs the REAL two-call PROSE + INTERPRETER loop on the scripted scene-1 lord so Gabriel can compare how faithfully the MCM-configured ACTION INTERPRETER (e.g. Grok) reads tags out of FRESH prose from different PROSE models. Each scripted turn makes two calls: (a) a PROSE call, forced to the argument model id via TestModelOverride, through the same seam the roleplay bench uses; (b) an INTERPRET call, with the override cleared so it resolves the MCM model, using ActionInterpreterPromptBuilder + the same one-shot pattern as cr.interpret_test. Expected use: set Grok in MCM, run \"cr.prose_interpret_test deepseek/deepseek-v4-pro\" then \"cr.prose_interpret_test z-ai/glm-5.2\", and read the log. This changes NOTHING in the live chat pipeline and is deliberately NOT part of cr.testall. The optional argument is the prose model id (default \"z-ai/glm-5.2\")."),
            ["provider_routing"] = new ConsoleCommandDoc("", "Prints which provider and base URL each role resolves to (prose, consensual, actions interpreter), without making a network call."),
            ["quest"] = new ConsoleCommandDoc("[name]", "Seeds a bandit-clear quest (near a real village, 10-day deadline, 300g/+3) on the NPC, through the real issue path. Tests prompt injection of the quest and the giver acknowledging it. Pair with cr.quest_done to test the reward."),
            ["quest_abandon"] = new ConsoleCommandDoc("[name]", "Force-abandons the NPC's outstanding quest (as if the player told them they quit), applying the broken-word penalty. Tests the abandon path without the LLM."),
            ["quest_complete"] = new ConsoleCommandDoc("[name]", "Simulates the NPC acknowledging the completed quest: closes the journal entry with success and pays the promised reward. Requires cr.quest_done first (the quest must already be in the awaiting-reward state)."),
            ["quest_done"] = new ConsoleCommandDoc("[name]", "Force-stamps the NPC's outstanding quest as satisfied (bypassing real events) so the giver will offer to reward it on the next exchange. Tests the completion + reward path without fighting a battle."),
            ["quest_gold"] = new ConsoleCommandDoc("[amount] [name]", "Seeds an outstanding ProvideGold quest on the NPC (e.g. a spouse's request for coin to support their household) so the Give Gold button: and the take_gold stamping path: can be tested deterministically, without waiting for the LLM to issue one or a child-support letter to arrive. Any non-zero gold the player gives the giver satisfies it; [amount] is flavour for the description (default 1000)."),
            ["quest_scout"] = new ConsoleCommandDoc("[name]", "Seeds a scout_army quest on the NPC, targeting their first enemy kingdom. Pair with cr.quest_done to test the completion reward, or let proximity detection fire naturally (OnHourlyTick) for a real-path test."),
            ["quest_void"] = new ConsoleCommandDoc("<#>", "Cancels the numbered quest from cr.quests_all as a clean NEUTRAL void: no relation penalty, no grudge, no broken-word. For unsticking an impossible or bugged quest (cr.quest_abandon instead applies the broken-word penalty, unjust for a quest that became impossible through no fault of the player)."),
            ["quests"] = new ConsoleCommandDoc("[name]", "Lists what a character has asked of you and where each of those tasks stands."),
            ["quests_all"] = new ConsoleCommandDoc("", "Lists EVERY outstanding quest across all givers, each with a number, so a stuck one can be cancelled by number with cr.quest_void. Unlike cr.quests [name], it is not scoped to one NPC."),
            ["rapport"] = new ConsoleCommandDoc("[name]", "Shows how a companion feels about their fellow companions (camp life)."),
            ["rapport_tick"] = new ConsoleCommandDoc("", "Runs a weekly camp-life pass now (compatibility nudges + any companion weddings)."),
            ["realm_news"] = new ConsoleCommandDoc("", "Seeds a high-magnitude WAR between two kingdoms so the \"TALK OF ALL THE REALM\" line is testable: then speak with any NPC who would have heard of it (the influence-loop realm-news polish)."),
            ["recall_letter"] = new ConsoleCommandDoc("", "Sends a letter-borne recall order to the FIRST away companion (path B): on a daily tick after the courier delay they abandon the errand and ride home. Use cr.missions to watch, or advance days."),
            ["recruit"] = new ConsoleCommandDoc("[name]", "Force-runs the join_clan action through the bridge (re-validates the gate, then moves the lord into the player's clan). Tests the defection path without the LLM."),
            ["recruit_info"] = new ConsoleCommandDoc("[name]", "Shows the lord-defection verdict for an NPC: the gathered gate facts and whether join_clan would be taught. Diagnostic only; mutates nothing."),
            ["recruit_notable"] = new ConsoleCommandDoc("[name]", "Forces the recruit_notable verb through the REAL bridge path on a settlement notable (a gang leader, headman, merchant, artisan, rural notable or preacher): it bequeaths the notable's gang/role to an eligible successor in the same town, then makes the notable a companion in the player's clan and party with a starting relation bonus. The mod's regard ledger is force-raised past the floor so the gate passes (test convenience). With a name fragment it targets that notable; without, the current conversation NPC. Reports the outcome, the successor, and the notable's new companion/party state."),
            ["relation"] = new ConsoleCommandDoc("<delta> [name]", "Simulates the change_relation action (an Other event), which is capped at +1 and held behind an eight-hour cooldown."),
            ["relation_intimate"] = new ConsoleCommandDoc("<delta> [name]", "The same as cr.relation but recorded as an Intimacy event: capped at +3, and it ignores the cooldown."),
            ["relation_reset"] = new ConsoleCommandDoc("[name]", "Clears the relation-gain cooldown stamp so the next gain lands immediately."),
            ["release_info"] = new ConsoleCommandDoc("[name]", "Shows the NEGOTIATED-RELEASE gate for an NPC captor: their Mercy, the heaviest live grudge they hold against you, and whether they can be TALKED into freeing you (persuasion) or would accept a RANSOM. A vendetta captor (heavy grudge / nemesis) refuses both. Use it to see which captors will yield before testing the release in a captive scene (cr.crc_scene, then plead your case in chat)."),
            ["reload_lore"] = new ConsoleCommandDoc("", "Reloads ModuleData/character_overrides.json and re-applies (or restores) the authored traits per the current \"Use custom traits\" toggle: no relaunch needed."),
            ["reload_prompts"] = new ConsoleCommandDoc("", "Reloads the prompt/lore DATA files from disk (Custom-first) without relaunching, for modders iterating on a total-overhaul: the narrative texts (world.txt, player_description.txt, behavior_guidelines*.txt, post_history_instructions.txt, council_seat.txt), setting.json, cultural_traditions.json, and jealousy_cultures.json. These are otherwise read only at session launch, so an edit needed a save reload before; cr.reload_lore covers ONLY character_overrides.json, which is why editing a prompt file and running reload_lore looked like the Custom folder was ignored. Styles are read per use, so they need no reload (just re-pick one). The next reply uses the fresh values (world state is rebuilt per message)."),
            ["reload_ui"] = new ConsoleCommandDoc("", "Dev hot-reload for the chat/memories/letter prefabs: re-reads any changed prefab XML from the DEPLOYED module folder and, if the chat OR the letter book is open, rebuilds its widget tree in place (same conversation / same letter, same history). Edit the file under the game's own Modules\\CalradiaRemembers\\GUI\\Prefabs (NOT the repo copy; a dotnet build would overwrite it), then run this to see the change without restarting. NOTE: this reloads XML only, never compiled C#; a change to a view-model still needs a full build + game restart."),
            ["remove_kink"] = new ConsoleCommandDoc("<kink> [name]", "Removes a kink from the NPC's profile."),
            ["rep_set"] = new ConsoleCommandDoc("<value> [name]", "Sets a character's personal regard for you outright, ignoring the pacing that normally governs it. For testing, or for repairing a campaign that has gone wrong."),
            ["rescue"] = new ConsoleCommandDoc("[name]", "Simulates freeing the named lord (or the conversation NPC) by a public siege: the lord and their family record a grateful memory and warm toward you, a few close friends warm too, and the captor rolls to discover it and hold a grudge. Bypasses battle detection and the once-per-lord gate."),
            ["reset"] = new ConsoleCommandDoc("", "The one to reach for when the mod seems stuck: no chat window opens, or one is open that will not close. It stands down whatever is jammed and lets conversations work again. It touches nothing in your save."),
            ["retainer"] = new ConsoleCommandDoc("[take|release|status|enable] [name|on|off]", "Retainer (ride_with_me): make an other-clan lord/lady ride IN the player's own party for a time, WITHOUT marriage and WITHOUT joining the player's clan (their Hero.Clan stays their own), and have a war with their faction force them to leave. - enable [on|off]: toggle the PLAYER-FACING ride_with_me / part_ways path (RetainerBehavior.Enabled, ON by default via the MCM \"Lords can ride in your party\" toggle; this sets a session-only override on top of it). With no argument, prints the current state. - take [name]: add the named other-clan lord to MobileParty.MainParty; reports roster/clan/occupation. - release [name]: remove a tracked retainer from the party; reports the resulting partyless state. - status: list every tracked retainer with clan + whether they are ACTUALLY still in MainParty. take/release/status drive the raw mechanism directly and work whether or not the path is enabled."),
            ["roundtable"] = new ConsoleCommandDoc("[on|off]", "With no argument, reports whether the council is enabled, whether a chat is open, who is present, and how many speakers a lap would give the floor to. With on/off, flips Enabled FOR THIS SESSION only (it is a code default, never persisted), so the feature can be play-tested without a rebuild. Per-turn cost lands in the log as [ROUNDTABLE TOKENS]."),
            ["seed_knowledge"] = new ConsoleCommandDoc("[test|clear]", "Gives several lords DIFFERENT situations so every knowledge pack has something to show: a SECRET love (must never be named), an OPEN love (only in private, to somebody they think well of), an open grievance against a third party, one character carrying both at once, and two hurt to different degrees (the grievously hurt one must refuse to ride out). Built because a live sweep found personal_bonds supplied 0 times out of 60 - not a bug, but a campaign with no grudges and no lovers in it. Then `test` puts the MATCHING question to each of them against the real model and judges the answers, so nobody has to go and hold six conversations by hand - and because it asks a real character with the context the GAME builds, it proves the host read the world and the packs composed, which a bench of hand-made facts cannot. Everything is reversible: cr.seed_knowledge clear puts hit points back where they were and drops the seeded grudges and lovers. Seeded grudges carry a [SEED] marker in their cause so a leftover is identifiable after a reload."),
            ["prompt_check"] = new ConsoleCommandDoc("", "The Prompt Composer: lists the prompt profiles found (stock, your own in Custom/Prompts, each mod's ModuleData/cr_prompts), marks the one chosen in MCM (\"Prompt Profile\") and its parents, and for each kind of character (spouse, companion, captive_scene, gang_leader, notable, wanderer, lord, default) the layout it gets and what the locks changed in it: an unknown section, a sealed or required one kept, a section left out of the layout kept at its stock place, a per-turn section above the cache marker. Reads the files again. Changes nothing."),
            ["prompt_dump"] = new ConsoleCommandDoc("[name|hero id]", "Writes the EXACT system prompt this character would be sent to a text file beside the log, and tells you where. No model is called and nothing is mutated: it builds the same context a real conversation builds, then puts the result on disk. Answers the one question that had no answer - when a character knows something odd, or fails to know something obvious, what did the model actually SEE? Also the harness for moving a prompt section: dump before, dump after, diff. [name] picks whom (default: whoever you are talking to)."),
            ["wire"] = new ConsoleCommandDoc("<on|off|dump>", "Reports what each LLM request COSTS, one [WIRE] line per call: how much of the prompt sits behind the prompt-cache breakpoint, how much is sent fresh every turn, how much of the body is conversation rather than prompt, and - the number that matters - how much of the cacheable prefix the NEXT turn can still read. On the second turn with a character, \"fully reused\" is right; \"diverges at N\" means a per-turn fact has drifted up into the cached prefix and every later turn is paying a full write for it. That is a real defect a player found by hand in September 2026, by saving two prompts and diffing them; this is the same measurement taken automatically. \"dump\" also writes each request body beside the log as CalradiaRemembers_wire_NNN.json so two turns can be diffed directly. Costs nothing when off, which is the default and is never persisted. Note that several speakers interleave (a room of witnesses, the action interpreter), so only consecutive turns with the SAME character are meaningful to compare."),
            ["memory_bench"] = new ConsoleCommandDoc("[name]", "KNOWLEDGE bench: asks a character six questions through the configured model and reports whether he USED what he was given and kept quiet about what he was not. Each probe hands him a controlled set of facts, so what he was and was not told is known exactly. The probes come in pairs on purpose: he must name his house's towns AND not receive his own governorship as news; he must not invent your purse AND not invent the numbers of a battle he missed; he must keep a secret love AND still speak an open grievance, since a character who mentions nobody would otherwise pass the secret test for the wrong reason. Literal checks where a word can be checked, a cold YES/NO judge on the interpreter model where the failure is a manner rather than a token, and every criterion names what counts as NOT failing so hedging is never scored as invention. [name] picks whom to ask (default: whoever you are talking to, else any lord). Real-LLM tool (spends tokens), deliberately NOT part of cr.testall. Full transcript in the mod log."),
            ["captive_talk_probe"] = new ConsoleCommandDoc("jail|info|open|free [tale|plain] [name]", "Engine spike (Gabriel, 24/10/2026, for a tale opened while the player is Rhagaea's prisoner): can a conversation open while the player is held in a castle or town dungeon? 'jail <lord>' takes the player prisoner into the nearest town or castle of that lord's house and brings the lord there; 'info [lord]' writes the engine's state (who holds the player, PlayerEncounter, menu, mission, where the lord is); 'open [tale|plain] <lord>' tries the tale-meeting or the plain-conversation staging door and writes the state before and after; 'free' ends the player's captivity. Everything goes to the log under [PROBE]. A spike, removed once the tale's engine is built."),
            ["cost_bench"] = new ConsoleCommandDoc("[plan|run] [cap]", "What the mod costs to play, per model and role, priced from OpenRouter's own bill (fearente, Gabriel, 24/10/2026). Configs/CalradiaRemembers_cost_bench.txt (written with defaults on first use) has four sections: [prose] each model plays the opening for real in Enhanced with no interpreter, then answers at turn 8 and at turn 18 of a long conversation (folded into a recap) over a synthetic history the same for every model, each after a warm-up reply, then writes a letter (start, middle and long priced apart, with signals: repeats, refusals, sermons, Earth references, recap recalled); [standard] the same in one call; [interpret] each model reads the whole action-bench catalog (or a sample per difficulty) plus ordinary replies, by difficulty (no action, simple, oblique, false lead), scored with a 95% interval; [fold] each Background model folds the same recap once. Then a prose x interpret grid, by addition, in dollars and in seconds waited. Each prose call's cacheable prefix is compared with the previous one and any change is named. Nothing is saved, no letter sent, every forced setting restored. 'plan' (the default) lists what would run; 'run [cap]' spends at most cap dollars (default 10) and writes the tables (Markdown, and [code] blocks for the Nexus page with the mod version and date), every billed call and the transcripts to CalradiaRemembers_cost_bench.log, and captures every request the prose and standard rows sent to CalradiaRemembers_cost_capture.json, so the same conversations can be replayed outside the game against any model (CostReplayLiveTests). Needs the PROSE, Interpret and Background roles on OpenRouter. Real-LLM tool, not part of cr.testall."),
            ["rp_bench"] = new ConsoleCommandDoc("[passes]", "Roleplay MODEL bench: plays two fixed scripted scenes (a lord affronted then appeased, and an intimate scene forced to Hardcore) through whatever LLM is configured in MCM, then writes a readable transcript plus advisory structural signals to CalradiaRemembers_rp_bench.log. Swap the roleplay model in MCM, re-run, and rank models BY READING. There is no automated judge: the user is the judge. Real-LLM tool (spends tokens); deliberately NOT part of cr.testall. [passes] defaults to 1 (one clean transcript)."),
            ["rp_verbs"] = new ConsoleCommandDoc("[name]", "RP with teeth, increment 1: reports which of the four court-action verbs (give_influence, lend_troops, sway_opinion, release_prisoner) are currently eligible for this NPC, and the amounts/lists CourtActionResolver would teach the LLM this conversation. Diagnostic only: the same resolvers the prompt gating and the bridge use, mutates nothing."),
            ["rumor"] = new ConsoleCommandDoc("[settlement]", "Opens a transient commoner conversation in the player's current settlement (or the named settlement if supplied). No profile is stored; the commoner exists only for this chat window. Tests the v1.1 Commoners path."),
            ["video"] = new ConsoleCommandDoc("play <file.crvid> [loop] | show <file> | replay | loop on|off | stop | status | swaprb on|off | flip on|off", "CR's own video player: plays a .crvid (a zip of JPEG frames, made by Tools/Video/make_crvid.py) in the open conversation's tale picture frame. Played once it comes back to its first frame; show sends any picture or video through the tale's own path (both skins); replay plays it again; loop makes it start over. swaprb and flip set the pixel order and orientation if colours or the picture come out wrong."),
            ["scenario_fire"] = new ConsoleCommandDoc("<VERB[:payload]> [heroName]", "Manually fires a trigger to test scenarios without waiting for the real event. An optional hero name becomes the event's primary hero (and their faction a context faction); the player is always included. E.g. cr.scenario_fire ON_DEATH Rhagaea."),
            ["scenarios"] = new ConsoleCommandDoc("", "List the loaded scripted-scenario rules and which one-shots have fired."),
            ["scheme"] = new ConsoleCommandDoc("[name]", "Force-plots a scheme: the named hero (or the current conversation NPC) plots against their most-hated rival lord. Use cr.scheme_advance to step it, cr.schemes to watch."),
            ["scheme_advance"] = new ConsoleCommandDoc("", "Advances every active scheme by one tick (no spawn): to test the lifecycle without waiting for daily ticks. Watch the result with cr.schemes."),
            ["scheme_assist"] = new ConsoleCommandDoc("[name]", "Force the player to abet the named plotter's secret scheme (bypasses the LLM). The plotter must regard you enough and the plot must be secret: set relation first with cr.relation."),
            ["scheme_warn"] = new ConsoleCommandDoc("[name]", "Force the player to warn the named hero of a secret plot against them (bypasses the LLM): exposes the scheme so the target can counter it on later ticks."),
            ["schemes"] = new ConsoleCommandDoc("", "Lists the feud schemes currently in motion (plotter → target, kind, state, progress)."),
            ["seed_accord"] = new ConsoleCommandDoc("<tribute|stipend|pact|hostage|ward> [name]", "Seeds a live council accord on the target hero (the current conversation NPC when no name is given), so the \"Standing accords\" section on that hero's Encyclopedia page can be checked at a glance."),
            ["send_barter"] = new ConsoleCommandDoc("[about]", "Sends your first companion to trade at a town (Trade); profit reaches you on return."),
            ["send_envoy"] = new ConsoleCommandDoc("[about]", "Sends your first companion as an envoy to a faction's town (Charm); their mood comes back in conversation."),
            ["send_news"] = new ConsoleCommandDoc("[about]", "Dispatches your first available companion to gather news: physically: they leave the party as their own clan party and ride to a town. Optional [about] scopes the destination (a faction, culture, or town: \"cr.send_news Sturgia\"). Use cr.mission_return to skip the travel and resolve now."),
            ["send_spy"] = new ConsoleCommandDoc("[about]", "Sends your first companion to scout a town (Roguery); intel comes back in conversation."),
            ["send_steal"] = new ConsoleCommandDoc("[about]", "Sends your first companion to lift coin from a town (Roguery); loot reaches you on return."),
            ["single_call_bench"] = new ConsoleCommandDoc("[passes] [modelId]", "Runs the single-call bench: for each scenario, one call has the tested model WRITE the NPC reply and self-tag it, then the SAME prose is read by the configured interpreter, and the two tag sets are compared. Reports the share of scenarios where they AGREE (the evidence for retiring the two-call pipeline). [passes] defaults to 1 (use 3 for majority scoring); \"temp=0.2\" sets the SINGLE-CALL temperature (default 0.6) to test whether a lower, extraction-friendly temperature recovers the deeds a prose-warm 0.6 drops; any other non-numeric argument is the single-call model id, e.g. \"cr.single_call_bench 3 temp=0.2 deepseek/deepseek-v4-flash-0731\". Set your interpreter model in MCM first (it is the reference cross-check). Real-LLM (spends tokens), NOT part of cr.testall. Writes CalradiaRemembers_single_call_bench.log."),
            ["single_call_probe"] = new ConsoleCommandDoc("[modelId]", "Runs the single-call composer+extractor prompt over a few scripted scenarios through one model (default: the currently configured scene model), forcing the model via TestModelOverride. Each scenario makes ONE call: the model writes the NPC reply AND grounds+emits the tags together. Writes prose + parsed tags + the RAW response (CHECK lines included) to CalradiaRemembers_single_call_probe.log. Use: \"cr.single_call_probe deepseek/deepseek-v4-flash-0731\". Spike tool, spends tokens, not in cr.testall."),
            ["skin"] = new ConsoleCommandDoc("[classic|manuscript|default]", "Changes the look of the chat window for your next conversation. Say default to hand the choice back to the Mod Options menu."),
            ["spend_influence"] = new ConsoleCommandDoc("[name]", "Forces spend_influence (04/07/2026, the reciprocal of give_influence) through the REAL bridge.ExecuteAction path, reporting the underlying facts (relation, the NPC clan's influence against the need threshold, the player clan's own reserve) so a refusal is diagnosable without guessing which gate failed."),
            ["spouse_divorce_accept"] = new ConsoleCommandDoc("", "Dispatches accept_divorce through the REAL bridge.ExecuteAction path (the same one a conversation uses) against the player's own spouse. Use after cr.spouse_divorce_demand to test the accept path without waiting on the LLM."),
            ["spouse_divorce_decline"] = new ConsoleCommandDoc("", "Dispatches decline_divorce through the REAL bridge.ExecuteAction path against the player's own spouse. Registers the refusal immediately (the grudge deepens) instead of waiting out the grace-period timeout."),
            ["spouse_divorce_demand"] = new ConsoleCommandDoc("", "Forces the player's CURRENT spouse into the demanding state right now (sets the persisted flag; the announcing letter is queued too, when the LLM is available). Says so plainly when the player is unmarried."),
            ["spouse_divorce_escalate"] = new ConsoleCommandDoc("", "Forces the player's CURRENT spouse into the estrangement state right now, bypassing the refusal-count gate (sets the persisted escalation record; the announcing letter is queued too, when the LLM is available). Says so plainly when the player is unmarried or already estranging."),
            ["spouse_divorce_info"] = new ConsoleCommandDoc("", "Reports whether the player's current spouse (if any) has a pending divorce demand or an active estrangement, and since/until which day. Read-only."),
            ["spouse_divorce_tick"] = new ConsoleCommandDoc("", "Runs one weekly evaluation right now (the demand-raising check, the grace-period refusal sweep, and the active-estrangement sweep: reconcile / walk-out / still pending), skipping the wait for the real weekly tick."),
            ["stance"] = new ConsoleCommandDoc("[name]", "Shows an NPC's posture toward the player (Affection/Trust/Respect/Fear) and the prompt block."),
            ["stance_intercept"] = new ConsoleCommandDoc("[name]", "\"Stance with teeth\" increment 2: forces the named lord (or the conversation NPC) through the PRODUCTION intercept path (the Intercept verdict). Unlike cr.intercept (which always bypasses the guard for raw pursuit testing), this respects InterceptionBehavior's own per-lord cooldown and its \"one pursuer at a time\" rule, so it may correctly report that no pursuit began."),
            ["stance_plot"] = new ConsoleCommandDoc("[name]", "\"Stance with teeth\" increment 2: forces the named lord (or the conversation NPC) to launch a REAL scheme against the PLAYER (the Plot verdict), bypassing the stance/trait evaluation so you can watch it mature with cr.scheme_advance / cr.schemes without waiting on the weekly tick."),
            ["stance_set"] = new ConsoleCommandDoc("<trust> <respect> <fear> [name]", "Sets the Trust/Respect/Fear axes directly (Affection stays on the reputation path) to test the posture block in conversation. Values are clamped to each axis's range."),
            ["stance_warning"] = new ConsoleCommandDoc("[name]", "\"Stance with teeth\" increment 2: forces the named lord (or the conversation NPC) into the Warning verdict now, bypassing the friendly-stance gate. If a real secret scheme currently targets the player, the queued letter NAMES the plotter; otherwise it reads as the generic friendly warmth. Pair with cr.stance_plot on a THIRD hero first to see the named case."),
            ["standing"] = new ConsoleCommandDoc("", "Your clan's tier and your record in the arena, as characters see them. Both change how they treat you."),
            ["stolen_love"] = new ConsoleCommandDoc("[status|seed|declare|divorce] [name]", "Drives the Stolen Love estrangement arc on a MARRIED NPC without waiting the weeks it normally takes, for testing. status: report the tracked phase; seed: begin an estrangement (bypasses the affair gate); declare: pull it to ReadyToDivorce and stamp the declaration; divorce: fire the divorce NOW (unmarry the couple + plant the jilted spouse's grudge). The NPC must be married to a third party, not to you. Needs \"Enable Stolen Love\" on for the arc to run naturally, but these forced steps apply regardless."),
            ["style"] = new ConsoleCommandDoc("<name>", "Chooses the prose every character writes in, from your next message on. cr.styles lists what you can pick."),
            ["style_show"] = new ConsoleCommandDoc("", "Prints the beginning of the rules currently injected, straight from the live cache, so you can confirm an edit to the .txt actually took (the lazy reload fired) before spending a call."),
            ["style_ui"] = new ConsoleCommandDoc("[on|off]", "Shows or hides the style picker button in the chat window's header. Off by default while the feature is play-tested (the same posture as the round-table kill-switch). Takes effect immediately, even on a chat that is already open."),
            ["styles"] = new ConsoleCommandDoc("", "Lists the prose styles you can choose with cr.style, and marks the one in use. Each is a plain text file in the mod's ModuleData/Styles folder, so you can write your own."),
            ["succession"] = new ConsoleCommandDoc("[predecessor]", "Simulates dynastic succession with the current player as the heir: reframes every stored NPC memory (drops the predecessor's private events, keeps the political/relational, marks it inherited). The predecessor defaults to your father/mother; pass a name to use a specific hero."),
            ["summary_queue"] = new ConsoleCommandDoc("[drain]", "Shows the durable conversation-summary queue: rich-summary jobs waiting to enrich a base \"Spoke with X.\" memory. They are persisted with the save, drained in the background, and replayed on load, so a promised plan's summary is not lost on save/quit/crash. 'drain' forces a pass now."),
            ["take_gold"] = new ConsoleCommandDoc("<amount> [name]", "The player hands the character that many denars, the reciprocal of cr.give_gold."),
            ["take_lover"] = new ConsoleCommandDoc("[name]", "Open relationship (Inc 3a) dev command: forces the named committed partner (or the conversation NPC) to take a lover of her own now, driving the REAL selection through the debug seam (bypassing only the weekly neglect roll) and reporting whether the taken lover is OPEN or SECRET. Her culture decides: an egalitarian partner needs open terms (use open_relationship first) and takes an OPEN lover; a harem / patriarchal culture (e.g. Aserai) takes a SECRET lover and may stray even without open terms (that uninvited path also needs the Jealousy MCM toggle on). Refuses, never a silent no-op."),
            ["teach_info"] = new ConsoleCommandDoc("[name]", "Shows the NPC's own value in every skill worth teaching (>= TeachSkillPolicy.TeacherSkillFloor), and their per-NPC cooldown state against the player (LastTaughtHour vs now). Mirrors the exact eligibility TeachSkillPolicy.CanTeach and ExecuteTeachSkill use, so this is a live preview of whether teach_skill would currently be taught (EncounterContext.TeachableSkills) and honoured."),
            ["test"] = new ConsoleCommandDoc("<name>", "Runs one self-test by name. cr.testall runs them all and prints the names."),
            ["testall"] = new ConsoleCommandDoc("", "Runs the mod's own self-tests and prints a summary. Fast, free, and it leaves your campaign as it found it. If you are reporting a bug, running this and sending the log tells us a great deal."),
            ["tick_probe"] = new ConsoleCommandDoc("[none|screen|state] [seconds]", "Opens the chosen host for a fixed window and reports how many times the map kept ticking underneath it. Run all three: 'none' says what a live map ticks at, 'screen' is how CR hosts panels today, 'state' is the candidate. The verdict lands in the log."),
            ["tryst"] = new ConsoleCommandDoc("[name]", "Open relationship (Inc 3b-a) dev command: forces the named partner (or the conversation NPC), who must already carry a taken lover (use cr.take_lover first), to have a tryst with him NOW, bypassing only the \"player is away\" gate and the weekly meeting roll. Runs the REAL tryst: it warms the bond, increments the tryst counter, records a private memory, and (for a SECRET affair) rolls the rising discovery chance that may expose it. First surfaces an OPEN lover to the player. Reports the tryst count and whether the lover is now known / the affair discovered. Refuses, never a silent no-op."),
            ["vram"] = new ConsoleCommandDoc("", "Logs one reading of your graphics memory. Useful if you suspect the mod of leaking it over a long session."),
            ["vram_noportrait"] = new ConsoleCommandDoc("[on|off]", "Suppresses every live character portrait in the chat (text-only). Run a captive scene with it ON and watch the [VRAM] trend: flat means the portrait tableau was the leak; still climbing means the naval map scene behind our overlay is the leak. Discriminating test only."),
            ["vram_watch"] = new ConsoleCommandDoc("[on|off]", "Toggles the frame-loop VRAM heartbeat that runs even with NO chat open and the game paused. Turn it on, sit on the map without opening a chat, and watch the [VRAM] watch lines: flat means our overlay drives the leak; climbing means the map screen leaks on its own."),
            ["patrol"] = new ConsoleCommandDoc("<companion> <settlement> [men]", "Orders a companion of your party to patrol a settlement (jaserms1, 16/10/2026), through the real path: close the console and the game's own troop screen opens with the companion as leader and [men] prefilled (default 20, at most half your men); choose the men and companions who ride, up to the leader's party size, or cancel. The patrol fights what it meets around the place, is sent back each hour it strays, and stays until recalled. Watch with cr.missions."),
            ["patrol_home"] = new ConsoleCommandDoc("<companion>", "Test path: brings a patrol back at once, wherever it is, with every man (wounded, prisoners and companions included) and its food. The real ways home are recall_companion in chat and a letter."),
            ["patrol_kit"] = new ConsoleCommandDoc("[companions] [men]", "Test helper (Gabriel, 17/10/2026). Fills a test party from the start of a game, for cr.patrol: mints [companions] wanderer companions (default 2, at most 6) into your clan and party, adds [men] recruits of your culture (default 60, at most 500; half basic, half one tier up) and grain to feed them."),
            ["edict"] = new ConsoleCommandDoc("[decree <kind> <town|realm> [days] | withdraw <id> | day | world]", "Edicts (Gabriel, 21/10/2026): with no argument, every edict in force or recently ended, its term, its grievance per town, where it was contested or forced off. decree: the town's holder (or the player's ruler, for realm) decrees one, the real rules applied; withdraw ends one; day runs one day (ends, grievances); world lets the world's lords weigh their towns once, whatever the MCM switch."),
            ["war_duty"] = new ConsoleCommandDoc("", "The vassal war duty as it stands today (Maifailun, 15/10/2026): the realm you are sworn to and since when, its wars and since when, the last day you served it (a battle against its enemy, a siege, a day in its army), today's verdict (owes, served, at peace, a new vassal...) and the reckoning in progress. Read-only; the ledger is kept even with the MCM switch off."),
            ["warcouncil"] = new ConsoleCommandDoc("[on|off|now]", "With no argument, reports whether the offer trigger is armed and its cooldown state. With on/off, flips Enabled FOR THIS SESSION only (a code default, never persisted), so the after-an-army-action offer can be play-tested without a rebuild. With 'now', forces the offer inquiry immediately (bypassing the in-army / notable / cooldown gates) to exercise the convene path."),
            ["weariness"] = new ConsoleCommandDoc("[name]", "Show a companion's war-weariness, band, tolerance, and retirement standing."),
            ["weary"] = new ConsoleCommandDoc("<value> [name]", "Set a companion's war-weariness directly (test path)."),
            ["weary_tick"] = new ConsoleCommandDoc("", "Runs a weekly war-weariness pass now (rest, retirement requests, drag-back enforcement)."),
            ["private"] = new ConsoleCommandDoc("", "Clears every witness from the open conversation, as an accepted private audience does: the fallback when a character agreed to speak privately and the room stayed full."),
            ["witness"] = new ConsoleCommandDoc("[witnessName]", "Adds a named witness to the currently open chat session. Primary test path for the multi-NPC feature: validates prompt injection, header UI, and the request_privacy round-trip without needing a real settlement context. The chat window must be open first (e.g. via cr.chat or a normal conversation)."),
            ["witnesses"] = new ConsoleCommandDoc("[name]", "Reports who the mod believes is close enough to overhear, which is who may be drawn into the conversation."),
            ["tale_test"] = new ConsoleCommandDoc("<tale id> [spouse's name]", "For testing a spouse tale that begins on the map, with nothing set up by hand: finds a spouse who fits it (the one named, else one of the tale's culture, 18 to 45, not with child, free to marry), divorces your present spouse if it is someone else, marries them, brings them into your party, raises their regard to what the tale needs, then opens its popup with the place and hour skipped. CHANGES THE CAMPAIGN (a divorce, a marriage): use a test save."),
            ["tale_open"] = new ConsoleCommandDoc("<tale id> <giver's name>", "For testing a tale that only a scenario rule opens (such as Rhagaea's night in the Adult Tales module): opens it now with that giver, through the same door as the rule, the rule's own conditions and dice skipped. Set the scene first (for the night: cr.captive_talk_probe jail Rhagaea). The tale's own rules still hold (content level, the giver's conditions, no other tale under way); it is first forgotten as played, so it can be tried again. Says what stands in the way otherwise."),
            ["tale_on_map"] = new ConsoleCommandDoc("<tale id> [anyway]", "For testing a tale that begins by itself on the map: opens its popup now, every condition checked but the day's dice (its giver travelling with you, the tale's rules, the hours still, the day, the giver's lands). With 'anyway', the place and the hour are skipped too. The tale is first forgotten as played or declined, so it can be tried again. Says what stands in the way otherwise."),
            ["story_check"] = new ConsoleCommandDoc("[name]", "Reloads the authored quest files (ModuleData/Quests and Quests/Custom) and lists what loaded and every problem found in them, in plain words. With a name (or in a conversation), says whether that character could give each quest now, and if not, why. For anyone writing a quest."),
            ["story_status"] = new ConsoleCommandDoc("", "Where the tale under way stands: its stage, who and where it is bound to, its progress."),
            ["story_start"] = new ConsoleCommandDoc("<quest id> [name]", "Binds an authored quest to that character (or the one you are speaking to) and takes it on at once, if they can give it. For testing a quest."),
            ["story_step"] = new ConsoleCommandDoc("", "Completes the current stage of the tale as though its objective were met. For testing a quest."),
            ["story_choose"] = new ConsoleCommandDoc("<choice id>", "Takes that open choice of the tale's current stage, however it would be taken. For walking each path of a branching quest."),
            ["story_abandon"] = new ConsoleCommandDoc("", "Sets the tale under way aside, without reward or penalty."),
            ["world_events"] = new ConsoleCommandDoc("[words]", "Lists stored world events, newest first, with their ids; add words to filter by what they say. The ids are what cr.world_event_remove, cr.world_event_secret and cr.world_event_hide take."),
            ["world_event_remove"] = new ConsoleCommandDoc("<id>", "Removes a world event: no one will hear of it any more. Memories characters already keep are separate (cr.memory, cr.forget)."),
            ["world_event_secret"] = new ConsoleCommandDoc("<id> [off]", "Keeps a world event known only to the people it names (a secret wedding: the two of them), in the news and in the long-term memory (ids from cr.world_events or cr.history). Those who know it hold it as a secret. 'off' makes it public again. Hides the news, not the facts."),
            ["world_event_hide"] = new ConsoleCommandDoc("<id> <name or hero id> [off]", "Keeps one character unaware of a world event, recent or long-term (ids from cr.world_events or cr.history); everyone else hears of it as before. 'off' lets them hear of it again."),
            ["world_event"] = new ConsoleCommandDoc("<what happened>", "A PLAYER tool (not a test): injects your own world rumour into the campaign through the same Feed door a third-party mod uses, so NPCs may gossip it. Any kingdom named in the text is auto-tagged so its people are likeliest to have heard it, and the settlement named in it becomes its place, so those near it hear it too. Reports how far and how long it will carry. Spreads by CR's hearsay rules (distance / faction / recency, as hearsay when it fits) -- NOT a \"make everyone know it instantly\" tool; for that on ONE NPC use cr.memory_add."),
            ["worldcond"] = new ConsoleCommandDoc("", "Force-runs the weekly world-conditions scan immediately (war looming between kingdoms, town hardship) and reports how many events each condition recorded. The same scan runs on its own weekly cadence."),
         };

      /// <summary>The description for a command, or null when none is written for it.</summary>
      public static ConsoleCommandDoc For(string command)
         => command != null && All.TryGetValue(command.Trim(), out ConsoleCommandDoc doc) ? doc : null;
   }
}
